import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { differenceInDays, startOfDay } from 'date-fns';

import Header from '../../components/navigation/Header';
import Footer from '../../components/Footer';
import Button from '../../components/ui/Button';
import { Checkbox } from '../../components/ui/Checkbox';
import Icon from '../../components/AppIcon';
import DateRangePicker from './components/DateRangePicker';
import PricingBreakdown from './components/PricingBreakdown';
import BookingSummary from './components/BookingSummary';

const BookingRequest = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const [formData, setFormData] = useState({
    startDate: null,
    endDate: null,
    includeInsurance: false,
    acceptCGU: false,
    message: ''
  });

  // Mock equipment data - would come from API/state in production
  const equipment = {
    id: 1,
    title: "Perceuse sans fil Bosch Professional",
    category: "Bricolage",
    dailyPrice: 15,
    cautionAmount: 150,
    images: [
    {
      url: "https://images.unsplash.com/photo-1695426585371-2052b20d260d",
      alt: "Professional cordless drill with battery pack and carrying case on wooden workbench in bright workshop setting"
    }],

    owner: {
      pseudonym: "PierreMart",
      avatar: "/assets/images/no_image.png",
      avatarAlt: "Professional headshot of French man with short dark hair wearing gray suit and white shirt smiling confidently",
      rating: 4.9,
      reviewCount: 42
    },
    unavailableDates: [
    new Date(2026, 1, 20),
    new Date(2026, 1, 21),
    new Date(2026, 1, 22)]

  };

  // Pricing constants
  const PLATFORM_COMMISSION_RATE = 0.15; // 15%
  const INSURANCE_DAILY_RATE = 2; // €2 per day

  // Calculate rental duration
  const rentalDays = formData?.startDate && formData?.endDate ?
  differenceInDays(formData?.endDate, formData?.startDate) + 1 :
  0;

  // Calculate pricing
  const equipmentTotal = rentalDays * equipment?.dailyPrice;
  const platformCommission = equipmentTotal * PLATFORM_COMMISSION_RATE;
  const insuranceFee = formData?.includeInsurance ? rentalDays * INSURANCE_DAILY_RATE : 0;
  const totalAmount = equipmentTotal + platformCommission + insuranceFee;

  const handleDateChange = (startDate, endDate) => {
    setFormData((prev) => ({ ...prev, startDate, endDate }));
    if (errors?.dates) {
      setErrors((prev) => ({ ...prev, dates: '' }));
    }
  };

  const handleInsuranceChange = (e) => {
    setFormData((prev) => ({ ...prev, includeInsurance: e?.target?.checked }));
  };

  const handleCGUChange = (e) => {
    setFormData((prev) => ({ ...prev, acceptCGU: e?.target?.checked }));
    if (errors?.acceptCGU) {
      setErrors((prev) => ({ ...prev, acceptCGU: '' }));
    }
  };

  const handleMessageChange = (e) => {
    setFormData((prev) => ({ ...prev, message: e?.target?.value }));
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData?.startDate || !formData?.endDate) {
      newErrors.dates = 'Veuillez sélectionner les dates de location';
    }

    if (!formData?.acceptCGU) {
      newErrors.acceptCGU = 'Vous devez accepter les conditions générales d\'utilisation';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handleSubmit = (e) => {
    e?.preventDefault();

    if (!validateForm()) return;

    setLoading(true);

    // Simulate API call
    setTimeout(() => {
      // Navigate to payment processing with booking data
      navigate('/traitement-paiement', {
        state: {
          equipment,
          bookingDetails: {
            startDate: formData?.startDate,
            endDate: formData?.endDate,
            rentalDays,
            equipmentTotal,
            platformCommission,
            insuranceFee,
            totalAmount,
            cautionAmount: equipment?.cautionAmount,
            includeInsurance: formData?.includeInsurance,
            message: formData?.message
          }
        }
      });
    }, 1500);
  };

  return (
    <div className="min-h-screen flex flex-col bg-surface">
      <Header />

      <main className="flex-1 py-8 md:py-12">
        <div className="container mx-auto px-4 max-w-6xl">
          {/* En-tête de page */}
          <div className="mb-6 md:mb-8">
            <button
              onClick={() => navigate(-1)}
              className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors mb-4">
              
              <Icon name="ArrowLeft" size={20} />
              <span>Retour</span>
            </button>
            <h1 className="text-h2 md:text-h1 font-heading text-foreground">
              Demande de réservation
            </h1>
            <p className="text-muted-foreground mt-2">
              Complétez les informations pour réserver cet équipement
            </p>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
              {/* Main Content */}
              <div className="lg:col-span-2 space-y-6">
                {/* Date Selection */}
                <div className="bg-white rounded-lg shadow-elevation-2 p-6">
                  <div className="flex items-center gap-3 mb-4">
                    <Icon name="Calendar" size={24} className="text-primary" />
                    <h2 className="text-h4 font-heading text-foreground">
                      Période de location
                    </h2>
                  </div>
                  <DateRangePicker
                    startDate={formData?.startDate}
                    endDate={formData?.endDate}
                    onChange={handleDateChange}
                    unavailableDates={equipment?.unavailableDates}
                    minDate={startOfDay(new Date())} />
                  
                  {errors?.dates &&
                  <p className="text-sm text-destructive mt-2">{errors?.dates}</p>
                  }
                  {rentalDays > 0 &&
                  <div className="mt-4 p-3 bg-accent/10 rounded-md">
                      <p className="text-sm text-accent-foreground">
                        <Icon name="Info" size={16} className="inline mr-1" />
                        Durée de location : <strong>{rentalDays} jour{rentalDays > 1 ? 's' : ''}</strong>
                      </p>
                    </div>
                  }
                </div>

                {/* Pricing Breakdown */}
                <div className="bg-white rounded-lg shadow-elevation-2 p-6">
                  <div className="flex items-center gap-3 mb-4">
                    <Icon name="Calculator" size={24} className="text-primary" />
                    <h2 className="text-h4 font-heading text-foreground">
                      Détail des prix
                    </h2>
                  </div>
                  <PricingBreakdown
                    dailyPrice={equipment?.dailyPrice}
                    rentalDays={rentalDays}
                    equipmentTotal={equipmentTotal}
                    platformCommission={platformCommission}
                    insuranceFee={insuranceFee}
                    totalAmount={totalAmount} />
                  
                </div>

                {/* Caution Information */}
                <div className="bg-white rounded-lg shadow-elevation-2 p-6">
                  <div className="flex items-center gap-3 mb-4">
                    <Icon name="Shield" size={24} className="text-warning" />
                    <h2 className="text-h4 font-heading text-foreground">
                      Caution demandée
                    </h2>
                  </div>
                  <div className="flex items-start gap-3 p-4 bg-warning/10 rounded-md">
                    <Icon name="AlertCircle" size={20} className="text-warning flex-shrink-0 mt-0.5" />
                    <div>
                      <p className="font-medium text-foreground mb-2">
                        Montant : {equipment?.cautionAmount?.toFixed(2)} €
                      </p>
                      <p className="text-sm text-muted-foreground mb-2">
                        <strong>La caution est une empreinte bancaire temporaire. Elle ne sera prélevée qu'en cas de dommage ou non-restitution.</strong>
                      </p>
                      <p className="text-sm text-muted-foreground">
                        Une autorisation bancaire sera effectuée sur votre carte lors de la réservation. Ce montant ne sera pas débité de votre compte. L'empreinte sera automatiquement libérée sous 48h après la restitution de l'équipement en bon état.
                      </p>
                    </div>
                  </div>
                </div>

                {/* Insurance Option */}
                <div className="bg-white rounded-lg shadow-elevation-2 p-6">
                  <div className="flex items-center gap-3 mb-4">
                    <Icon name="ShieldCheck" size={24} className="text-success" />
                    <h2 className="text-h4 font-heading text-foreground">
                      Assurance (optionnelle)
                    </h2>
                  </div>
                  <Checkbox
                    id="insurance"
                    checked={formData?.includeInsurance}
                    onChange={handleInsuranceChange}
                    label={`Ajouter l'assurance tous risques (+${INSURANCE_DAILY_RATE}€/jour)`}
                    description="Couvre les dommages accidentels, le vol et la casse. Franchise de 50€. Recommandé pour votre tranquillité d'esprit." />
                  
                  {formData?.includeInsurance &&
                  <div className="mt-3 p-3 bg-success/10 rounded-md">
                      <p className="text-sm text-success-foreground">
                        <Icon name="Check" size={16} className="inline mr-1" />
                        Assurance ajoutée : {insuranceFee?.toFixed(2)} € pour {rentalDays} jour{rentalDays > 1 ? 's' : ''}
                      </p>
                    </div>
                  }
                </div>

                {/* Optional Message */}
                <div className="bg-white rounded-lg shadow-elevation-2 p-6">
                  <div className="flex items-center gap-3 mb-4">
                    <Icon name="MessageSquare" size={24} className="text-primary" />
                    <h2 className="text-h4 font-heading text-foreground">
                      Message au propriétaire (optionnel)
                    </h2>
                  </div>
                  <textarea
                    value={formData?.message}
                    onChange={handleMessageChange}
                    placeholder="Présentez-vous et expliquez votre besoin..."
                    rows={4}
                    className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2" />
                  
                </div>

                {/* CGU Acceptance */}
                <div className="bg-white rounded-lg shadow-elevation-2 p-6">
                  <Checkbox
                    id="cgu"
                    checked={formData?.acceptCGU}
                    onChange={handleCGUChange}
                    label="J'accepte les conditions générales d'utilisation"
                    description={
                    <span>
                        En cochant cette case, vous acceptez nos{' '}
                        <a href="/cgu" target="_blank" className="text-primary hover:underline">
                          conditions générales d'utilisation
                        </a>
                        {' '}et notre{' '}
                        <a href="/politique-confidentialite" target="_blank" className="text-primary hover:underline">
                          politique de confidentialité
                        </a>
                        .
                      </span>
                    }
                    error={errors?.acceptCGU} />
                  
                </div>

                {/* Bouton d'envoi */}
                <Button
                  type="submit"
                  size="lg"
                  fullWidth
                  loading={loading}
                  disabled={!formData?.startDate || !formData?.endDate || !formData?.acceptCGU}
                  className="bg-accent hover:bg-accent/90 text-accent-foreground">
                  
                  <Icon name="Send" size={20} className="mr-2" />
                  Envoyer la demande
                </Button>
              </div>

              {/* Sidebar - Booking Summary */}
              <div className="lg:col-span-1">
                <div className="sticky top-24">
                  <BookingSummary
                    equipment={equipment}
                    startDate={formData?.startDate}
                    endDate={formData?.endDate}
                    rentalDays={rentalDays}
                    totalAmount={totalAmount} />
                  
                </div>
              </div>
            </div>
          </form>
        </div>
      </main>

      <Footer />
    </div>);

};

export default BookingRequest;

