import React, { useState, useEffect } from 'react';
import Header from '../../components/navigation/Header';
import Icon from '../../components/AppIcon';
import ProfileTab from './components/ProfileTab';
import ActivityHistoryTab from './components/ActivityHistoryTab';
import DocumentsTab from './components/DocumentsTab';
import SettingsSection from './components/SettingsSection';
import Footer from '../../components/Footer';
import ReportModal from '../../components/ReportModal';
import Button from '../../components/ui/Button';
import { useAuth } from '../../contexts/AuthContext';
import profileService from '../../services/profileService';


const UserProfileDocuments = () => {
  const { user, userProfile } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [showReportModal, setShowReportModal] = useState(false);
  const [loading, setLoading] = useState(true);

  const [userData, setUserData] = useState(null);

  const [activities] = useState([
  {
    id: 1,
    type: 'rental',
    title: 'Location de Perceuse sans fil Bosch',
    description: 'Location confirmée pour 3 jours',
    date: '2026-02-12T10:30:00',
    status: 'active',
    amount: 45.00,
    user: {
      name: 'Thomas Martin',
      avatar: "/assets/images/no_image.png",
      avatarAlt: 'Professional headshot of French man with short dark hair wearing gray suit and white shirt smiling confidently'
    },
    actionLabel: 'Voir détails',
    actionIcon: 'Eye'
  },
  {
    id: 2,
    type: 'payment',
    title: 'Paiement reçu',
    description: 'Paiement pour la location de Tondeuse électrique',
    date: '2026-02-10T14:20:00',
    status: 'completed',
    amount: 120.00,
    actionLabel: 'Télécharger reçu',
    actionIcon: 'Download'
  },
  {
    id: 3,
    type: 'booking',
    title: 'Nouvelle demande de réservation',
    description: 'Demande pour Échelle télescopique 5m',
    date: '2026-02-09T09:15:00',
    status: 'pending',
    amount: 35.00,
    user: {
      name: 'Sophie Bernard',
      avatar: "/assets/images/no_image.png",
      avatarAlt: 'Professional portrait of French woman with blonde hair in elegant black dress smiling warmly in modern office environment'
    },
    actionLabel: 'Répondre',
    actionIcon: 'MessageSquare'
  },
  {
    id: 4,
    type: 'message',
    title: 'Nouveau message',
    description: 'Question sur la disponibilité de votre Scie circulaire',
    date: '2026-02-08T16:45:00',
    status: 'completed',
    user: {
      name: 'Lucas Petit',
      avatar: "/assets/images/no_image.png",
      avatarAlt: 'Casual portrait of young French man with curly brown hair wearing blue denim shirt smiling in outdoor setting'
    },
    actionLabel: 'Répondre',
    actionIcon: 'MessageSquare'
  },
  {
    id: 5,
    type: 'rental',
    title: 'Location terminée',
    description: 'Karcher K5 Premium rendu en bon état',
    date: '2026-02-07T11:00:00',
    status: 'completed',
    amount: 80.00,
    user: {
      name: 'Emma Rousseau',
      avatar: "/assets/images/no_image.png",
      avatarAlt: 'Professional headshot of French woman with red hair wearing green blouse smiling confidently in bright studio setting'
    },
    actionLabel: 'Laisser un avis',
    actionIcon: 'Star'
  },
  {
    id: 6,
    type: 'review',
    title: 'Nouvel avis reçu',
    description: 'Pierre Durand a laissé un avis 5 étoiles',
    date: '2026-02-06T13:30:00',
    status: 'completed',
    user: {
      name: 'Pierre Durand',
      avatar: "/assets/images/no_image.png",
      avatarAlt: 'Professional portrait of middle-aged French man with gray hair wearing navy suit and striped tie in corporate office setting'
    },
    actionLabel: 'Voir l\'avis',
    actionIcon: 'Eye'
  },
  {
    id: 7,
    type: 'booking',
    title: 'Réservation annulée',
    description: 'Annulation de la location de Ponceuse orbitale',
    date: '2026-02-05T08:20:00',
    status: 'cancelled',
    amount: 25.00,
    user: {
      name: 'Julie Moreau',
      avatar: "/assets/images/no_image.png",
      avatarAlt: 'Casual portrait of young French woman with long dark hair wearing casual white t-shirt smiling in natural outdoor lighting'
    }
  },
  {
    id: 8,
    type: 'payment',
    title: 'Virement effectué',
    description: 'Transfert vers votre compte bancaire',
    date: '2026-02-03T10:00:00',
    status: 'completed',
    amount: 450.00,
    actionLabel: 'Voir détails',
    actionIcon: 'Eye'
  }]
  );

  const [documents, setDocuments] = useState([
  {
    id: 1,
    type: 'identity',
    fileName: 'carte_identite_marie_dubois.pdf',
    uploadDate: '2026-01-15T10:30:00',
    status: 'approved',
    approvedDate: '2026-01-16T14:20:00'
  },
  {
    id: 2,
    type: 'address',
    fileName: 'facture_electricite_janvier_2026.pdf',
    uploadDate: '2026-01-15T10:35:00',
    status: 'approved',
    approvedDate: '2026-01-16T14:25:00'
  },
  {
    id: 3,
    type: 'insurance',
    fileName: 'attestation_assurance_responsabilite_civile.pdf',
    uploadDate: '2026-01-20T09:15:00',
    status: 'pending'
  },
  {
    id: 4,
    type: 'bank',
    fileName: 'rib_banque_populaire.pdf',
    uploadDate: '2026-02-01T11:45:00',
    status: 'rejected',
    rejectionReason: 'Le document est illisible. Veuillez télécharger une version de meilleure qualité.'
  }]
  );

  const [settings, setSettings] = useState({
    notifications: {
      newBooking: true,
      messages: true,
      paymentConfirmed: true,
      returnReminder: true,
      documentReminder: true,
      dailyDigest: false,
      promotions: false
    }
  });

  // Load real user profile data from Supabase
  useEffect(() => {
    const loadUserProfile = async () => {
      if (!user) {
        setLoading(false);
        return;
      }

      try {
        const { data: profile, error } = await profileService?.getProfile(user?.id);
        
        if (error) {
          console.error('Erreur lors du chargement de profile:', error);
          setLoading(false);
          return;
        }

        if (profile) {
          // Map database fields to component format
          setUserData({
            pseudonym: profile?.pseudo || 'Utilisateur',
            email: profile?.email || user?.email || '',
            phone: profile?.phone || '',
            address: profile?.address || '',
            city: profile?.city || '',
            postalCode: profile?.postal_code || '',
            bio: profile?.bio || '',
            avatar: profile?.avatar_url || "/assets/images/no_image.png",
            avatarAlt: `Photo de profil de ${profile?.pseudo || 'utilisateur'}`,
            role: 'owner',
            isVerified: true,
            stripeConnectStatus: profile?.stripe_account_id ? 'completed' : 'pending',
            stats: {
              listings: 0,
              bookings: 0,
              rating: 0,
              reviews: 0
            }
          });
        }
      } catch (error) {
        console.error('Erreur lors du chargement de user profile:', error);
      } finally {
        setLoading(false);
      }
    };

    loadUserProfile();
  }, [user]);

  const handleUpdateProfile = async (updatedData) => {
    if (!user?.id) return;

    try {
      // Map component fields to database fields
      const dbFields = {
        pseudo: updatedData?.pseudonym,
        email: updatedData?.email,
        phone: updatedData?.phone,
        address: updatedData?.address,
        city: updatedData?.city,
        postal_code: updatedData?.postalCode
      };

      const { data, error } = await profileService?.updateProfileFields(user?.id, dbFields);
      
      if (error) {
        console.error('Erreur lors de la mise à jour de profile:', error);
        alert('Erreur lors de la mise à jour du profil');
        return;
      }

      // Update local state
      setUserData((prev) => ({
        ...prev,
        ...updatedData
      }));

      alert('Profil mis à jour avec succès');
    } catch (error) {
      console.error('Erreur lors de la mise à jour de profile:', error);
      alert('Erreur lors de la mise à jour du profil');
    }
  };

  const handleUploadDocument = (documentType, file) => {
    const newDocument = {
      id: documents?.length + 1,
      type: documentType,
      fileName: file?.name,
      uploadDate: new Date()?.toISOString(),
      status: 'pending'
    };
    setDocuments((prev) => [...prev, newDocument]);
  };

  const handleDeleteDocument = (documentId) => {
    setDocuments((prev) => prev?.filter((doc) => doc?.id !== documentId));
  };

  const handleUpdateSettings = (updatedSettings) => {
    setSettings((prev) => ({
      ...prev,
      ...updatedSettings
    }));
  };

  const tabs = [
  { id: 'profile', label: 'Profil', icon: 'User' },
  { id: 'activity', label: 'Historique', icon: 'Activity' },
  { id: 'documents', label: 'Documents', icon: 'FileText' },
  { id: 'settings', label: 'Paramètres', icon: 'Settings' }];


  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-[#c8e8f5] via-[#f5c6a8] to-[#fbe8d0] flex flex-col">
        <Header />
        <main className="main-content flex items-center justify-center">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
            <p className="text-muted-foreground">Chargement du profil...</p>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  if (!user) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-[#c8e8f5] via-[#f5c6a8] to-[#fbe8d0] flex flex-col">
        <Header />
        <main className="main-content flex items-center justify-center">
          <div className="text-center">
            <Icon name="AlertCircle" size={48} className="mx-auto mb-4 text-warning" />
            <h2 className="text-2xl font-bold text-foreground mb-2">Connexion requise</h2>
            <p className="text-muted-foreground mb-4">Veuillez vous connecter pour accéder à votre profil</p>
            <Button onClick={() => window.location.href = '/authentification'}>Se connecter</Button>
          </div>
        </main>
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-[#c8e8f5] via-[#f5c6a8] to-[#fbe8d0] flex flex-col">
      <Header />
      <main className="main-content">
        <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-6 md:py-8 lg:py-12">
          <div className="mb-6 md:mb-8">
            <h1 className="text-2xl md:text-3xl lg:text-4xl font-bold text-foreground mb-2">
              Mon Compte
            </h1>
            <p className="text-sm md:text-base text-muted-foreground">
              Gérez votre profil, vos documents et vos préférences
            </p>
          </div>

          <div className="bg-card rounded-xl shadow-elevation-2 mb-6 overflow-x-auto">
            <div className="flex border-b border-border min-w-max">
              {tabs?.map((tab) =>
              <button
                key={tab?.id}
                onClick={() => setActiveTab(tab?.id)}
                className={`flex items-center gap-2 px-4 md:px-6 py-3 md:py-4 text-sm md:text-base font-medium transition-smooth whitespace-nowrap ${
                activeTab === tab?.id ?
                'text-primary border-b-2 border-primary' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`
                }>
                
                  <Icon name={tab?.icon} size={20} />
                  <span>{tab?.label}</span>
                </button>
              )}
              <div className="flex items-center gap-4">
                <Button variant="outline" size="sm">
                  <Icon name="MessageSquare" size={16} />
                  Envoyer un message
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setShowReportModal(true)}>
                  
                  <Icon name="Flag" size={16} />
                  Signaler
                </Button>
              </div>
            </div>
          </div>

          <div className="transition-smooth">
            {activeTab === 'profile' && userData &&
            <ProfileTab userData={userData} onUpdateProfile={handleUpdateProfile} />
            }
            {activeTab === 'activity' &&
            <ActivityHistoryTab activities={activities} />
            }
            {activeTab === 'documents' &&
            <DocumentsTab
              documents={documents}
              onUploadDocument={handleUploadDocument}
              onDeleteDocument={handleDeleteDocument} />

            }
            {activeTab === 'settings' &&
            <SettingsSection settings={settings} onUpdateSettings={handleUpdateSettings} />
            }
          </div>
        </div>
      </main>
      <Footer />

      {/* Report Modal */}
      {showReportModal &&
      <ReportModal
        onClose={() => setShowReportModal(false)}
        reportType="user"
        targetId={userData?.pseudonym}
        targetName={userData?.pseudonym} />

      }
    </div>);

};

export default UserProfileDocuments;
