/**
 * Geolocation service with Haversine distance calculation
 */

const EARTH_RADIUS_KM = 6371;

/**
 * Convert degrees to radians
 */
const toRadians = (degrees) => {
  return degrees * (Math.PI / 180);
};

/**
 * Calculate distance between two coordinates using Haversine formula
 * Formula: distance = 2 × R × arcsin(sqrt(sin²((lat2-lat1)/2) + cos(lat1)×cos(lat2)×sin²((lon2-lon1)/2)))
 * where R = 6371 km (Earth's radius)
 */
export const calculateDistance = (lat1, lon1, lat2, lon2) => {
  const dLat = toRadians(lat2 - lat1);
  const dLon = toRadians(lon2 - lon1);
  
  const a = 
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRadians(lat1)) * Math.cos(toRadians(lat2)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  
  const c = 2 * Math.asin(Math.sqrt(a));
  const distance = EARTH_RADIUS_KM * c;
  
  return distance; // Returns distance in kilometers
};

/**
 * Get user's current position using browser geolocation API
 */
export const getCurrentPosition = () => {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      reject(new Error('La géolocalisation n\'est pas supportée par votre navigateur'));
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        resolve({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy
        });
      },
      (error) => {
        let errorMessage = 'Erreur de géolocalisation';
        
        switch (error.code) {
          case error.PERMISSION_DENIED:
            errorMessage = 'Autorisation de géolocalisation refusée. Veuillez activer la géolocalisation dans les paramètres de votre navigateur.';
            break;
          case error.POSITION_UNAVAILABLE:
            errorMessage = 'Position non disponible. Veuillez réessayer.';
            break;
          case error.TIMEOUT:
            errorMessage = 'Délai d\'attente dépassé. Veuillez réessayer.';
            break;
          default:
            errorMessage = 'Erreur inconnue lors de la géolocalisation.';
        }
        
        reject(new Error(errorMessage));
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0
      }
    );
  });
};

/**
 * Filter annonces by distance from user location
 */
export const filterByDistance = (annonces, userLocation, maxDistanceKm) => {
  if (!userLocation || !annonces) return annonces;

  return annonces?.map(annonce => {
      // Calculate distance if annonce has coordinates
      if (annonce?.latitude && annonce?.longitude) {
        const distance = calculateDistance(
          userLocation?.latitude,
          userLocation?.longitude,
          annonce?.latitude,
          annonce?.longitude
        );
        
        return {
          ...annonce,
          distance: distance,
          distanceText: `À ${distance?.toFixed(1)} km de vous`
        };
      }
      
      return annonce;
    })?.filter(annonce => {
      // Filter by max distance if distance is calculated
      if (annonce?.distance !== undefined) {
        return annonce?.distance <= maxDistanceKm;
      }
      // Keep annonces without coordinates
      return true;
    })?.sort((a, b) => {
      // Sort by distance (closest first)
      if (a?.distance !== undefined && b?.distance !== undefined) {
        return a?.distance - b?.distance;
      }
      // Annonces without distance go to the end
      if (a?.distance === undefined) return 1;
      if (b?.distance === undefined) return -1;
      return 0;
    });
};

/**
 * Add distance information to a single annonce
 */
export const addDistanceInfo = (annonce, userLocation) => {
  if (!userLocation || !annonce?.latitude || !annonce?.longitude) {
    return annonce;
  }

  const distance = calculateDistance(
    userLocation?.latitude,
    userLocation?.longitude,
    annonce?.latitude,
    annonce?.longitude
  );

  return {
    ...annonce,
    distance,
    distanceText: `À ${distance?.toFixed(1)} km de vous`
  };
};

/**
 * Check if geolocation is available
 */
export const isGeolocationAvailable = () => {
  return 'geolocation' in navigator;
};

/**
 * Watch user position for real-time updates
 */
export const watchPosition = (onSuccess, onError) => {
  if (!navigator.geolocation) {
    onError?.(new Error('Géolocalisation non supportée'));
    return null;
  }

  const watchId = navigator.geolocation?.watchPosition(
    (position) => {
      onSuccess?.({
        latitude: position?.coords?.latitude,
        longitude: position?.coords?.longitude,
        accuracy: position?.coords?.accuracy
      });
    },
    (error) => {
      onError?.(error);
    },
    {
      enableHighAccuracy: true,
      timeout: 10000,
      maximumAge: 30000
    }
  );

  return watchId;
};

/**
 * Stop watching position
 */
export const clearWatch = (watchId) => {
  if (watchId && navigator.geolocation) {
    navigator.geolocation?.clearWatch(watchId);
  }
};

export default {
  calculateDistance,
  getCurrentPosition,
  filterByDistance,
  addDistanceInfo,
  isGeolocationAvailable,
  watchPosition,
  clearWatch
};
