import React, { useState } from 'react';
import Button from '../../../components/ui/Button';
import authService from '../../../services/authService';

const SocialAuth = () => {
  const [loading, setLoading] = useState({ google: false, facebook: false });
  const [error, setError] = useState(null);

  const handleSocialLogin = async (provider) => {
    setError(null);
    setLoading(prev => ({ ...prev, [provider?.toLowerCase()]: true }));

    try {
      const { data, error } = await authService?.signInWithOAuth(provider?.toLowerCase());
      
      if (error) {
        console.error(`Erreur de connexion ${provider}:`, error);
        setError(`Impossible de se connecter avec ${provider}. Vérifiez que le fournisseur est configuré dans Supabase.`);
        setLoading(prev => ({ ...prev, [provider?.toLowerCase()]: false }));
      }
      // If successful, user will be redirected to OAuth provider
      // After authorization, they'll be redirected back to /auth/retour
    } catch (err) {
      console.error(`Erreur OAuth ${provider}:`, err);
      setError(`Une erreur est survenue lors de la connexion avec ${provider}.`);
      setLoading(prev => ({ ...prev, [provider?.toLowerCase()]: false }));
    }
  };

  return (
    <div className="space-y-3 md:space-y-4">
      <div className="relative">
        <div className="absolute inset-0 flex items-center">
          <div className="w-full border-t border-border"></div>
        </div>
        <div className="relative flex justify-center text-sm">
          <span className="px-4 bg-card text-muted-foreground">ou</span>
        </div>
      </div>
      {error && (
        <div className="p-3 bg-destructive/10 border border-destructive/20 rounded-lg text-sm text-destructive">
          {error}
        </div>
      )}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        <Button
          variant="outline"
          size="default"
          onClick={() => handleSocialLogin('google')}
          loading={loading?.google}
          disabled={loading?.google || loading?.facebook}
          iconName="Mail"
          iconPosition="left"
          className="bg-white hover:bg-gray-50 text-gray-700 border-gray-300"
        >
          Se connecter avec Google
        </Button>

        <Button
          variant="outline"
          size="default"
          onClick={() => handleSocialLogin('facebook')}
          loading={loading?.facebook}
          disabled={loading?.google || loading?.facebook}
          iconName="Facebook"
          iconPosition="left"
          className="bg-[#1877F2] hover:bg-[#166FE5] text-white border-[#1877F2]"
        >
          Se connecter avec Facebook
        </Button>
      </div>
      <p className="text-xs text-center text-muted-foreground">
        En vous connectant avec un réseau social, un profil sera automatiquement créé
      </p>
    </div>
  );
};

export default SocialAuth;