import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Header from '../../components/navigation/Header';
import Footer from '../../components/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import BeforePhotosSection from './components/BeforePhotosSection';
import AfterPhotosSection from './components/AfterPhotosSection';
import ComparisonView from './components/ComparisonView';

const PhotosEtatDesLieux = () => {
  const { reservationId } = useParams();
  const navigate = useNavigate();
  const [activeView, setActiveView] = useState('upload'); // 'upload' or 'comparison'

  // Mock reservation data
  const reservation = {
    id: reservationId || '1',
    equipmentTitle: 'Perceuse sans fil Bosch Professional',
    equipmentImage: "/assets/images/no_image.png",
    startDate: '2026-02-20',
    endDate: '2026-02-23',
    status: 'ongoing',
    owner: {
      pseudonym: 'BricoleurPro',
      isCurrentUser: true
    },
    renter: {
      pseudonym: 'JeanDupont',
      isCurrentUser: false
    }
  };

  // Mock photos state
  const [beforePhotos, setBeforePhotos] = useState([
  {
    id: '1',
    url: '/assets/images/no_image.png',
    timestamp: '2026-02-19T14:30:00',
    uploadedBy: 'BricoleurPro',
    gpsCoordinates: '48.8566, 2.3522',
    comment: 'État neuf, aucune rayure visible'
  }]
  );

  const [afterPhotos, setAfterPhotos] = useState([]);

  const handleBeforePhotoAdd = (photo) => {
    setBeforePhotos([...beforePhotos, photo]);
  };

  const handleAfterPhotoAdd = (photo) => {
    setAfterPhotos([...afterPhotos, photo]);
  };

  const handleBeforePhotoDelete = (photoId) => {
    setBeforePhotos(beforePhotos?.filter((p) => p?.id !== photoId));
  };

  const handleAfterPhotoDelete = (photoId) => {
    setAfterPhotos(afterPhotos?.filter((p) => p?.id !== photoId));
  };

  const canUploadBefore = reservation?.owner?.isCurrentUser && reservation?.status !== 'completed';
  const canUploadAfter = reservation?.renter?.isCurrentUser && (reservation?.status === 'ongoing' || reservation?.status === 'completed');

  return (
    <div className="min-h-screen flex flex-col bg-surface">
      <Header />

      <main className="flex-1 container mx-auto px-4 py-6 md:py-8">
        {/* En-tête de page */}
        <div className="mb-6">
          <button
            onClick={() => navigate(-1)}
            className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors mb-4">
            
            <Icon name="ArrowLeft" size={20} />
            <span>Retour</span>
          </button>
          <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-2">Photos d'État des Lieux</h1>
          <p className="text-muted-foreground">Documentation de l'état du matériel avant et après location</p>
        </div>

        {/* Equipment Info Card */}
        <div className="bg-white rounded-lg shadow-elevation-1 p-4 mb-6">
          <div className="flex items-center gap-4">
            <img
              src={reservation?.equipmentImage}
              alt={reservation?.equipmentTitle}
              className="w-20 h-20 object-cover rounded-lg" />
            
            <div className="flex-1">
              <h2 className="font-semibold text-foreground mb-1">{reservation?.equipmentTitle}</h2>
              <div className="flex flex-wrap gap-4 text-sm text-muted-foreground">
                <div className="flex items-center gap-1">
                  <Icon name="Calendar" size={14} />
                  <span>{new Date(reservation?.startDate)?.toLocaleDateString('fr-FR')} - {new Date(reservation?.endDate)?.toLocaleDateString('fr-FR')}</span>
                </div>
                <div className="flex items-center gap-1">
                  <Icon name="User" size={14} />
                  <span>Propriétaire: {reservation?.owner?.pseudonym}</span>
                </div>
                <div className="flex items-center gap-1">
                  <Icon name="UserCheck" size={14} />
                  <span>Locataire: {reservation?.renter?.pseudonym}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* View Toggle */}
        <div className="flex gap-2 mb-6">
          <Button
            variant={activeView === 'upload' ? 'default' : 'outline'}
            onClick={() => setActiveView('upload')}
            iconName="Upload"
            className={activeView === 'upload' ? 'bg-[#17a2b8] hover:bg-[#138496]' : ''}>
            
            Gestion des photos
          </Button>
          <Button
            variant={activeView === 'comparison' ? 'default' : 'outline'}
            onClick={() => setActiveView('comparison')}
            iconName="Columns"
            className={activeView === 'comparison' ? 'bg-[#17a2b8] hover:bg-[#138496]' : ''}
            disabled={beforePhotos?.length === 0 && afterPhotos?.length === 0}>
            
            Vue comparative
          </Button>
        </div>

        {/* Content */}
        {activeView === 'upload' ?
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Before Photos Section */}
            <BeforePhotosSection
            photos={beforePhotos}
            canUpload={canUploadBefore}
            onPhotoAdd={handleBeforePhotoAdd}
            onPhotoDelete={handleBeforePhotoDelete} />
          

            {/* After Photos Section */}
            <AfterPhotosSection
            photos={afterPhotos}
            canUpload={canUploadAfter}
            onPhotoAdd={handleAfterPhotoAdd}
            onPhotoDelete={handleAfterPhotoDelete} />
          
          </div> :

        <ComparisonView
          beforePhotos={beforePhotos}
          afterPhotos={afterPhotos} />

        }

        {/* Info Banner */}
        <div className="mt-6 bg-[#17a2b8]/10 border border-[#17a2b8]/20 rounded-lg p-4">
          <div className="flex gap-2">
            <Icon name="Info" size={18} className="text-[#17a2b8] flex-shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-medium text-foreground mb-2">Importance des photos d'état des lieux</p>
              <ul className="text-sm text-muted-foreground space-y-1">
                <li>• Les photos servent de preuve en cas de litige</li>
                <li>• Elles déterminent la libération ou la retenue de la caution</li>
                <li>• Chaque photo inclut un horodatage et des métadonnées de localisation</li>
                <li>• Prenez des photos claires de tous les angles du matériel</li>
              </ul>
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>);

};

export default PhotosEtatDesLieux;
