import React, { useState, useRef } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Image from '../../../components/AppImage';
import CameraCaptureModal from '../../../pages/create-listing/components/CameraCaptureModal';

const BeforePhotosSection = ({ photos, canUpload, onPhotoAdd, onPhotoDelete }) => {
  const fileInputRef = useRef(null);
  const [isCameraModalOpen, setIsCameraModalOpen] = useState(false);
  const [selectedPhoto, setSelectedPhoto] = useState(null);
  const [showCommentModal, setShowCommentModal] = useState(false);
  const [currentComment, setCurrentComment] = useState('');

  const handleFileSelect = (e) => {
    const files = Array.from(e?.target?.files || []);
    files?.forEach((file) => {
      const newPhoto = {
        id: Math.random()?.toString(36)?.substr(2, 9),
        url: URL.createObjectURL(file),
        file,
        timestamp: new Date()?.toISOString(),
        uploadedBy: 'Utilisateur actuel',
        gpsCoordinates: '48.8566, 2.3522', // Mock GPS
        comment: ''
      };
      onPhotoAdd(newPhoto);
    });
  };

  const handleCameraCapture = (file, previewUrl) => {
    const newPhoto = {
      id: Math.random()?.toString(36)?.substr(2, 9),
      url: previewUrl,
      file,
      timestamp: new Date()?.toISOString(),
      uploadedBy: 'Utilisateur actuel',
      gpsCoordinates: '48.8566, 2.3522', // Mock GPS
      comment: ''
    };
    onPhotoAdd(newPhoto);
  };

  const handleAddComment = (photo) => {
    setSelectedPhoto(photo);
    setCurrentComment(photo?.comment || '');
    setShowCommentModal(true);
  };

  const handleSaveComment = () => {
    // In real app, update photo comment via API
    console.log('Save comment for photo:', selectedPhoto?.id, currentComment);
    setShowCommentModal(false);
    setSelectedPhoto(null);
    setCurrentComment('');
  };

  const formatTimestamp = (timestamp) => {
    const date = new Date(timestamp);
    return date?.toLocaleDateString('fr-FR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="bg-white rounded-lg shadow-elevation-1 p-6">
      {/* Section En-tête */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <div className="p-2 bg-success/10 rounded-lg">
            <Icon name="Camera" size={20} className="text-success" />
          </div>
          <div>
            <h2 className="text-lg font-semibold text-foreground">Photos avant location</h2>
            <p className="text-xs text-muted-foreground">Ajoutées par le propriétaire</p>
          </div>
        </div>
        <div className="px-2 py-1 bg-success/10 rounded-full text-xs font-medium text-success">
          {photos?.length} photo{photos?.length > 1 ? 's' : ''}
        </div>
      </div>

      {/* Zone de téléversement */}
      {canUpload && (
        <div className="mb-4 border-2 border-dashed border-border rounded-lg p-4 text-center">
          <Icon name="Upload" size={32} className="mx-auto text-muted-foreground mb-2" />
          <p className="text-sm text-muted-foreground mb-3">Ajoutez des photos de l'état initial du matériel</p>
          <div className="flex gap-2 justify-center">
            <Button
              variant="outline"
              size="sm"
              iconName="Image"
              onClick={() => fileInputRef?.current?.click()}
            >
              Sélectionner
            </Button>
            <Button
              variant="outline"
              size="sm"
              iconName="Camera"
              onClick={() => setIsCameraModalOpen(true)}
            >
              Prendre une photo
            </Button>
          </div>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            multiple
            onChange={handleFileSelect}
            className="hidden"
          />
        </div>
      )}

      {/* Photos Grid */}
      {photos?.length === 0 ? (
        <div className="text-center py-8">
          <Icon name="ImageOff" size={48} className="mx-auto text-muted-foreground mb-2" />
          <p className="text-sm text-muted-foreground">Aucune photo avant location</p>
        </div>
      ) : (
        <div className="space-y-4">
          {photos?.map((photo) => (
            <div key={photo?.id} className="border border-border rounded-lg overflow-hidden">
              <div className="aspect-video relative">
                <Image
                  src={photo?.url}
                  alt="Photo avant location"
                  className="w-full h-full object-cover"
                />
                {canUpload && (
                  <button
                    onClick={() => onPhotoDelete(photo?.id)}
                    className="absolute top-2 right-2 p-2 bg-error text-white rounded-full hover:bg-error/90 transition-colors"
                  >
                    <Icon name="Trash2" size={16} />
                  </button>
                )}
              </div>
              <div className="p-3 bg-surface space-y-2">
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <Icon name="Clock" size={12} />
                  <span>{formatTimestamp(photo?.timestamp)}</span>
                </div>
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <Icon name="MapPin" size={12} />
                  <span>{photo?.gpsCoordinates}</span>
                </div>
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <Icon name="User" size={12} />
                  <span>{photo?.uploadedBy}</span>
                </div>
                {photo?.comment && (
                  <div className="mt-2 p-2 bg-white rounded border border-border">
                    <p className="text-xs text-foreground">{photo?.comment}</p>
                  </div>
                )}
                {canUpload && (
                  <Button
                    variant="outline"
                    size="xs"
                    iconName="MessageSquare"
                    onClick={() => handleAddComment(photo)}
                    fullWidth
                  >
                    {photo?.comment ? 'Modifier le commentaire' : 'Ajouter un commentaire'}
                  </Button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Camera Modal */}
      <CameraCaptureModal
        isOpen={isCameraModalOpen}
        onClose={() => setIsCameraModalOpen(false)}
        onCapture={handleCameraCapture}
      />

      {/* Comment Modal */}
      {showCommentModal && (
        <div className="fixed inset-0 z-modal flex items-center justify-center p-4 bg-black/50">
          <div className="bg-white rounded-lg shadow-elevation-4 max-w-md w-full">
            <div className="border-b border-border px-6 py-4 flex items-center justify-between">
              <h3 className="text-lg font-semibold text-foreground">Ajouter un commentaire</h3>
              <button
                onClick={() => setShowCommentModal(false)}
                className="p-2 hover:bg-surface rounded-md transition-colors"
              >
                <Icon name="X" size={20} />
              </button>
            </div>
            <div className="p-6">
              <textarea
                value={currentComment}
                onChange={(e) => setCurrentComment(e?.target?.value)}
                placeholder="Décrivez l'état du matériel sur cette photo..."
                rows={4}
                maxLength={500}
                className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 resize-none"
              />
              <p className="text-xs text-muted-foreground mt-2">{currentComment?.length}/500 caractères</p>
            </div>
            <div className="bg-surface border-t border-border px-6 py-4 flex items-center justify-end gap-3">
              <Button variant="outline" onClick={() => setShowCommentModal(false)}>
                Annuler
              </Button>
              <Button onClick={handleSaveComment} className="bg-[#17a2b8] hover:bg-[#138496]">
                Enregistrer
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default BeforePhotosSection;



