import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import annonceService from '../../services/annonceService';
import Icon from '../../components/AppIcon';
import Header from '../../components/navigation/Header';
import Footer from '../../components/Footer';
import normaliserAnnonce from '../../utils/annonceNormalizer';
import { construireUrlAnnonce } from '../../utils/listingUrl';

const UserAnnonces = () => {
  const { user, isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const [annonces, setAnnonces] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/authentification');
      return;
    }

    fetchUserAnnonces();
  }, [isAuthenticated, user]);

  const fetchUserAnnonces = async () => {
    if (!user?.id) return;

    try {
      setLoading(true);
      setError(null);
      const { data, error: fetchError } = await annonceService?.getUserAnnonces(user?.id);

      if (fetchError) {
        setError('Erreur lors du chargement de vos annonces');
        console.error('Fetch annonces error:', fetchError);
      } else {
        const annoncesNormalisees = (data || [])?.map((annonce) => normaliserAnnonce(annonce));
        setAnnonces(annoncesNormalisees);
      }
    } catch (err) {
      setError('Une erreur est survenue');
      console.error('Fetch error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (annonceId) => {
    if (!window.confirm('Etes-vous sur de vouloir supprimer cette annonce ?')) {
      return;
    }

    try {
      const { error: deleteError } = await annonceService?.deleteAnnonce(annonceId);

      if (deleteError) {
        alert('Erreur lors de la suppression');
        console.error('Delete error:', deleteError);
      } else {
        fetchUserAnnonces();
      }
    } catch (err) {
      alert('Une erreur est survenue');
      console.error('Delete error:', err);
    }
  };

  const getStatusBadge = (statut) => {
    const statusConfig = {
      en_attente: { label: 'En attente', color: 'bg-yellow-100 text-yellow-800' },
      publiee: { label: 'Publiee', color: 'bg-green-100 text-green-800' },
      refusee: { label: 'Refusee', color: 'bg-red-100 text-red-800' },
      draft: { label: 'Brouillon', color: 'bg-gray-100 text-gray-800' },
      archivee: { label: 'Archivee', color: 'bg-slate-100 text-slate-800' },
      pending: { label: 'En attente', color: 'bg-yellow-100 text-yellow-800' },
      published: { label: 'Publiee', color: 'bg-green-100 text-green-800' },
      rejected: { label: 'Refusee', color: 'bg-red-100 text-red-800' }
    };

    const config = statusConfig?.[statut] || statusConfig?.en_attente;
    return (
      <span className={`px-2 py-1 rounded-full text-xs font-medium ${config?.color}`}>
        {config?.label}
      </span>
    );
  };

  if (loading) {
    return (
      <>
        <Header />
        <div className="min-h-screen bg-gray-50 pt-24 pb-12">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-center py-20">
              <div className="text-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#17a2b8] mx-auto"></div>
                <p className="mt-4 text-gray-600">Chargement de vos annonces...</p>
              </div>
            </div>
          </div>
        </div>
        <Footer />
      </>
    );
  }

  return (
    <>
      <Header />
      <div className="min-h-screen bg-gray-50 pt-24 pb-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900">Mes Annonces</h1>
            <p className="mt-2 text-gray-600">
              Gere vos annonces et suivez leur statut
            </p>
          </div>

          {error && (
            <div className="mb-6 bg-red-50 border border-red-200 rounded-lg p-4">
              <div className="flex items-center gap-2">
                <Icon name="AlertCircle" size={20} className="text-red-600" />
                <p className="text-red-800">{error}</p>
              </div>
            </div>
          )}

          {!loading && annonces?.length === 0 && (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-12 text-center">
              <div className="max-w-md mx-auto">
                <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Icon name="Package" size={32} className="text-gray-400" />
                </div>
                <h2 className="text-xl font-semibold text-gray-900 mb-2">
                  Vous n'avez pas encore d'annonces
                </h2>
                <p className="text-gray-600 mb-6">
                  Commencez a partager votre materiel avec vos voisins
                </p>
                <Link
                  to="/creer-annonce"
                  className="inline-flex items-center gap-2 px-6 py-3 bg-[#17a2b8] text-white rounded-lg hover:bg-[#138496] transition-colors"
                >
                  <Icon name="Plus" size={20} />
                  Creer une annonce
                </Link>
              </div>
            </div>
          )}

          {annonces?.length > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {annonces?.map((annonce) => (
                <div
                  key={annonce?.id}
                  className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden hover:shadow-md transition-shadow"
                >
                  <div className="relative h-48 bg-gray-200">
                    {annonce?.image ? (
                      <img
                        src={annonce?.image}
                        alt={annonce?.titre || 'Annonce'}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <Icon name="Image" size={48} className="text-gray-400" />
                      </div>
                    )}
                    <div className="absolute top-3 right-3">
                      {getStatusBadge(annonce?.statut)}
                    </div>
                  </div>

                  <div className="p-4">
                    <h3 className="text-lg font-semibold text-gray-900 mb-2 line-clamp-1">
                      {annonce?.titre}
                    </h3>
                    <p className="text-gray-600 text-sm mb-3 line-clamp-2">
                      {annonce?.description}
                    </p>
                    <div className="flex items-center justify-between mb-4">
                      <div className="text-[#17a2b8] font-bold text-lg">
                        {annonce?.prix_jour ? `${Number(annonce?.prix_jour)?.toFixed(2)}€/jour` : 'Prix non defini'}
                      </div>
                    </div>

                    <div className="flex gap-2">
                      <Link
                        to={construireUrlAnnonce(annonce)}
                        className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors text-sm"
                      >
                        <Icon name="Eye" size={16} />
                        Voir
                      </Link>
                      <Link
                        to={`/creer-annonce?edit=${annonce?.id}`}
                        className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-[#17a2b8] text-white rounded-lg hover:bg-[#138496] transition-colors text-sm"
                      >
                        <Icon name="Edit" size={16} />
                        Modifier
                      </Link>
                      <button
                        onClick={() => handleDelete(annonce?.id)}
                        className="flex items-center justify-center gap-2 px-3 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 transition-colors text-sm"
                      >
                        <Icon name="Trash2" size={16} />
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {annonces?.length > 0 && (
            <div className="mt-8 text-center">
              <Link
                to="/creer-annonce"
                className="inline-flex items-center gap-2 px-6 py-3 bg-[#17a2b8] text-white rounded-lg hover:bg-[#138496] transition-colors"
              >
                <Icon name="Plus" size={20} />
                Creer une nouvelle annonce
              </Link>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </>
  );
};

export default UserAnnonces;
