const ADMIN_ACCESS_STORAGE_KEY = "admin_access_granted_at";
const ADMIN_ACCESS_TTL_MS = 30 * 60 * 1000; // 30 minutes

function getSessionStorage() {
  if (typeof window === "undefined") return null;
  return window.sessionStorage;
}

export function grantAdminAccess() {
  const storage = getSessionStorage();
  if (!storage) return;
  storage.setItem(ADMIN_ACCESS_STORAGE_KEY, String(Date.now()));
}

export function clearAdminAccess() {
  const storage = getSessionStorage();
  if (!storage) return;
  storage.removeItem(ADMIN_ACCESS_STORAGE_KEY);
}

export function isAdminAccessGranted() {
  const storage = getSessionStorage();
  if (!storage) return false;

  const rawValue = storage.getItem(ADMIN_ACCESS_STORAGE_KEY);
  if (!rawValue) return false;

  const grantedAt = Number(rawValue);
  if (!Number.isFinite(grantedAt)) {
    clearAdminAccess();
    return false;
  }

  if (Date.now() - grantedAt > ADMIN_ACCESS_TTL_MS) {
    clearAdminAccess();
    return false;
  }

  return true;
}
