import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../../components/navigation/Header';
import Footer from '../../components/Footer';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import Select from '../../components/ui/Select';
import Icon from '../../components/AppIcon';
import demandeService from '../../services/demandeService';
import categoryService from '../../services/categoryService';
import { useAuth } from '../../contexts/AuthContext';

const CreateDemandRequest = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState([]);
  const [errors, setErrors] = useState({});

  const [formData, setFormData] = useState({
    titre: '',
    description: '',
    categorie_slug: '',
    ville: '',
    rayon_km: 10,
    prix_max: '',
    dispo_de: '',
    dispo_a: ''
  });

  useEffect(() => {
    if (!user) {
      navigate('/authentification');
      return;
    }
    loadCategories();
  }, [user]);

  const loadCategories = async () => {
    try {
      const { data } = await categoryService?.getCategories();
      if (data) {
        setCategories(data);
      }
    } catch (error) {
      console.error('Erreur lors du chargement des catégories :', error);
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors?.[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData?.titre?.trim()) {
      newErrors.titre = 'Le titre est requis';
    }

    if (!formData?.description?.trim()) {
      newErrors.description = 'La description est requise';
    }

    if (!formData?.categorie_slug) {
      newErrors.categorie_slug = 'La catégorie est requise';
    }

    if (!formData?.ville?.trim()) {
      newErrors.ville = 'La ville est requise';
    }

    if (!formData?.prix_max || formData?.prix_max <= 0) {
      newErrors.prix_max = 'Le prix maximum doit être supérieur à 0';
    }

    if (!formData?.dispo_de) {
      newErrors.dispo_de = 'La date de début est requise';
    }

    if (!formData?.dispo_a) {
      newErrors.dispo_a = 'La date de fin est requise';
    }

    if (formData?.dispo_de && formData?.dispo_a && new Date(formData?.dispo_de) > new Date(formData?.dispo_a)) {
      newErrors.dispo_a = 'La date de fin doit être après la date de début';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handleSubmit = async (e) => {
    e?.preventDefault();

    if (!validateForm()) return;

    setLoading(true);

    try {
      const { data, error } = await demandeService?.createDemande({
        ...formData,
        statut: 'open',
        moderation_status: 'pending'
      });

      if (error) {
        setErrors({ submit: error?.message || 'Erreur lors de la création de la demande' });
        return;
      }

      // Redirection vers le tableau de bord utilisateur
      navigate('/tableau-bord-utilisateur?tab=demandes');
    } catch (error) {
      console.error("Erreur d'envoi :", error);
      setErrors({ submit: 'Une erreur est survenue. Veuillez réessayer.' });
    } finally {
      setLoading(false);
    }
  };

  const categoryOptions = categories?.map(cat => ({
    value: cat?.nom,
    label: cat?.nom
  }));

  const rayonOptions = [
    { value: '5', label: '5 km' },
    { value: '10', label: '10 km' },
    { value: '25', label: '25 km' },
    { value: '50', label: '50 km' },
    { value: '100', label: '100 km' }
  ];

  return (
    <div className="min-h-screen flex flex-col bg-surface">
      <Header />

      <main className="flex-1 container mx-auto px-4 py-6 md:py-8">
        <div className="max-w-3xl mx-auto">
          {/* En-tête */}
          <div className="mb-6">
            <button
              onClick={() => navigate(-1)}
              className="flex items-center gap-2 text-muted-foreground hover:text-foreground mb-4 transition-smooth"
            >
              <Icon name="ArrowLeft" size={20} />
              <span>Retour</span>
            </button>
            <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
              Créer une demande de location
            </h1>
            <p className="text-muted-foreground">
              Décrivez l'équipement que vous recherchez et nous vous mettrons en relation avec des propriétaires
            </p>
          </div>

          {/* Formulaire */}
          <form onSubmit={handleSubmit} className="bg-white rounded-lg shadow-elevation-2 p-6 space-y-6">
            {/* Titre */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Titre de la demande *
              </label>
              <Input
                type="text"
                placeholder="Ex: Recherche perceuse sans fil pour 3 jours"
                value={formData?.titre}
                onChange={(e) => handleChange('titre', e?.target?.value)}
                error={errors?.titre}
              />
              {errors?.titre && (
                <p className="text-sm text-error mt-1">{errors?.titre}</p>
              )}
            </div>

            {/* Description */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Description *
              </label>
              <textarea
                className="w-full px-4 py-3 border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary resize-none"
                rows={4}
                placeholder="Décrivez précisément l'équipement recherché, vos besoins et contraintes..."
                value={formData?.description}
                onChange={(e) => handleChange('description', e?.target?.value)}
              />
              {errors?.description && (
                <p className="text-sm text-error mt-1">{errors?.description}</p>
              )}
            </div>

            {/* Catégorie */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Catégorie *
              </label>
              <Select
                options={categoryOptions}
                value={formData?.categorie_slug}
                onChange={(e) => handleChange('categorie_slug', e?.target?.value)}
                placeholder="Sélectionnez une catégorie"
              />
              {errors?.categorie_slug && (
                <p className="text-sm text-error mt-1">{errors?.categorie_slug}</p>
              )}
            </div>

            {/* Localisation */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-foreground mb-2">
                  Ville *
                </label>
                <Input
                  type="text"
                  placeholder="Ex: Paris"
                  value={formData?.ville}
                  onChange={(e) => handleChange('ville', e?.target?.value)}
                  error={errors?.ville}
                />
                {errors?.ville && (
                  <p className="text-sm text-error mt-1">{errors?.ville}</p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-foreground mb-2">
                  Rayon de recherche
                </label>
                <Select
                  options={rayonOptions}
                  value={formData?.rayon_km?.toString()}
                  onChange={(e) => handleChange('rayon_km', parseInt(e?.target?.value))}
                />
              </div>
            </div>

            {/* Prix */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-2">
                Prix maximum par jour (€) *
              </label>
              <Input
                type="number"
                placeholder="Ex: 25"
                value={formData?.prix_max}
                onChange={(e) => handleChange('prix_max', e?.target?.value)}
                min="0"
                step="0.01"
                error={errors?.prix_max}
              />
              {errors?.prix_max && (
                <p className="text-sm text-error mt-1">{errors?.prix_max}</p>
              )}
            </div>

            {/* Dates */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-foreground mb-2">
                  Date de début *
                </label>
                <Input
                  type="date"
                  value={formData?.dispo_de}
                  onChange={(e) => handleChange('dispo_de', e?.target?.value)}
                  min={new Date()?.toISOString()?.split('T')?.[0]}
                  error={errors?.dispo_de}
                />
                {errors?.dispo_de && (
                  <p className="text-sm text-error mt-1">{errors?.dispo_de}</p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-foreground mb-2">
                  Date de fin *
                </label>
                <Input
                  type="date"
                  value={formData?.dispo_a}
                  onChange={(e) => handleChange('dispo_a', e?.target?.value)}
                  min={formData?.dispo_de || new Date()?.toISOString()?.split('T')?.[0]}
                  error={errors?.dispo_a}
                />
                {errors?.dispo_a && (
                  <p className="text-sm text-error mt-1">{errors?.dispo_a}</p>
                )}
              </div>
            </div>

            {/* Erreur d'envoi */}
            {errors?.submit && (
              <div className="bg-error/10 border border-error rounded-lg p-4">
                <p className="text-sm text-error">{errors?.submit}</p>
              </div>
            )}

            {/* Actions */}
            <div className="flex gap-4 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => navigate(-1)}
                className="flex-1"
              >
                Annuler
              </Button>
              <Button
                type="submit"
                disabled={loading}
                className="flex-1"
              >
                {loading ? (
                  <>
                    <Icon name="Loader" size={20} className="animate-spin" />
                    <span>Création...</span>
                  </>
                ) : (
                  'Publier la demande'
                )}
              </Button>
            </div>
          </form>

          {/* Encadré d'information */}
          <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
            <div className="flex gap-3">
              <Icon name="Info" size={20} className="text-blue-600 flex-shrink-0 mt-0.5" />
              <div>
                <h3 className="font-semibold text-blue-900 mb-1">Comment ça marche ?</h3>
                <ul className="text-sm text-blue-800 space-y-1">
                  <li>• Votre demande sera modérée sous 24h</li>
                  <li>• Notre algorithme recherchera automatiquement des équipements correspondants</li>
                  <li>• Vous recevrez des propositions de propriétaires</li>
                  <li>• Vous pourrez accepter ou refuser chaque proposition</li>
                </ul>
              </div>
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default CreateDemandRequest;




