import React, { useState } from 'react';
import { format, addMonths, subMonths, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay, startOfDay } from 'date-fns';
import { fr } from 'date-fns/locale';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { Checkbox } from '../../../components/ui/Checkbox';
import Input from '../../../components/ui/Input';
import { cn } from '../../../utils/cn';

const DisponibilitesStep = ({ formData, updateFormData, errors }) => {
  const [currentMonth, setCurrentMonth] = useState(startOfMonth(new Date()));

  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(currentMonth);
  const daysInMonth = eachDayOfInterval({ start: monthStart, end: monthEnd });

  const handlePreviousMonth = () => {
    setCurrentMonth(subMonths(currentMonth, 1));
  };

  const handleNextMonth = () => {
    setCurrentMonth(addMonths(currentMonth, 1));
  };

  const isDateUnavailable = (date) => {
    return formData?.unavailableDates?.some((unavailableDate) =>
      isSameDay(startOfDay(date), startOfDay(new Date(unavailableDate)))
    );
  };

  const handleDateClick = (date) => {
    const dateString = date?.toISOString();
    const isCurrentlyUnavailable = isDateUnavailable(date);

    if (isCurrentlyUnavailable) {
      const updatedDates = formData?.unavailableDates?.filter(
        (d) => !isSameDay(startOfDay(new Date(d)), startOfDay(date))
      );
      updateFormData('unavailableDates', updatedDates);
    } else {
      updateFormData('unavailableDates', [...formData?.unavailableDates, dateString]);
    }
  };

  const weekDays = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
  const fullWeekDays = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];

  const getWeekDay = (date) => {
    const day = date?.getDay();
    return day === 0 ? 6 : day - 1;
  };

  const firstDayOffset = getWeekDay(monthStart);

  // Initialize pickup/return data if not present
  const pickupDays = formData?.pickupDays || [];
  const returnDays = formData?.returnDays || [];
  const pickupTimeStart = formData?.pickupTimeStart || '08:30';
  const pickupTimeEnd = formData?.pickupTimeEnd || '19:30';
  const returnTimeStart = formData?.returnTimeStart || '08:30';
  const returnTimeEnd = formData?.returnTimeEnd || '19:30';

  const handleDayToggle = (day, type) => {
    const fieldName = type === 'pickup' ? 'pickupDays' : 'returnDays';
    const currentDays = type === 'pickup' ? pickupDays : returnDays;
    
    if (currentDays?.includes(day)) {
      updateFormData(fieldName, currentDays?.filter(d => d !== day));
    } else {
      updateFormData(fieldName, [...currentDays, day]);
    }
  };

  const handleTimeChange = (field, value) => {
    // Validate time constraints
    if (field === 'pickupTimeStart' && value < '08:30') {
      return; // Don't allow pickup before 08:30
    }
    if (field === 'returnTimeEnd' && value > '19:30') {
      return; // Don't allow return after 19:30
    }
    updateFormData(field, value);
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-xl font-semibold text-foreground mb-2">Disponibilités</h2>
        <p className="text-sm text-muted-foreground">Indiquez les dates où votre matériel n'est pas disponible</p>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 items-start">
        {/* Calendar */}
        <div className="space-y-4 w-full max-w-[28rem]">
          {/* Calendar En-tête */}
          <div className="flex items-center justify-between">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handlePreviousMonth}
              iconName="ChevronLeft"
            />
            <h3 className="text-lg font-semibold capitalize">
              {format(currentMonth, 'MMMM yyyy', { locale: fr })}
            </h3>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleNextMonth}
              iconName="ChevronRight"
            />
          </div>

          {/* Week Days En-tête */}
          <div className="grid grid-cols-7 gap-1">
            {weekDays?.map((day) => (
              <div key={day} className="text-center text-sm font-medium text-muted-foreground py-2">
                {day}
              </div>
            ))}
          </div>

          {/* Calendar Grid */}
          <div className="grid grid-cols-7 gap-1">
            {/* Empty cells for offset */}
            {Array.from({ length: firstDayOffset })?.map((_, index) => (
              <div key={`empty-${index}`} className="h-10 w-10" />
            ))}

            {/* Date cells */}
            {daysInMonth?.map((date) => {
              const isUnavailable = isDateUnavailable(date);
              const isToday = isSameDay(date, new Date());

              return (
                <button
                  key={date?.toISOString()}
                  type="button"
                  onClick={() => handleDateClick(date)}
                  className={cn(
                    'h-10 w-10 mx-auto rounded-md text-sm font-medium transition-colors',
                    'hover:bg-accent/20 focus:outline-none focus:ring-2 focus:ring-primary',
                    isUnavailable && 'bg-error/20 text-error line-through',
                    isToday && !isUnavailable && 'border-2 border-primary',
                    !isUnavailable && 'hover:bg-accent/10'
                  )}
                >
                  {format(date, 'd')}
                </button>
              );
            })}
          </div>

          {/* Legend */}
          <div className="flex flex-wrap gap-4 text-xs text-muted-foreground">
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 rounded border-2 border-primary" />
              <span>Aujourd'hui</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 rounded bg-error/20 line-through" />
              <span>Indisponible</span>
            </div>
          </div>
        </div>

        {/* Pickup and Return Scheduling */}
        <div className="space-y-6 bg-surface rounded-lg border border-border p-6">
          <div>
            <h3 className="text-lg font-semibold text-foreground mb-2">Horaires de récupération et restitution</h3>
            <p className="text-xs text-muted-foreground">Les récupérations ne peuvent pas avoir lieu avant 8h30 et les restitutions après 19h30</p>
          </div>

          {/* Pickup Days */}
          <div className="space-y-3">
            <label className="text-sm font-medium text-foreground">Jours de récupération disponibles</label>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
              {fullWeekDays?.map((day) => (
                <div key={`pickup-${day}`} className="flex items-center">
                  <Checkbox
                    label={day}
                    checked={pickupDays?.includes(day)}
                    onChange={() => handleDayToggle(day, 'pickup')}
                  />
                </div>
              ))}
            </div>
          </div>

          {/* Pickup Time Range */}
          <div className="space-y-3">
            <label className="text-sm font-medium text-foreground">Horaires de récupération</label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <Input
                type="time"
                label="Heure de début"
                value={pickupTimeStart}
                onChange={(e) => handleTimeChange('pickupTimeStart', e?.target?.value)}
                min="08:30"
                required
              />
              <Input
                type="time"
                label="Heure de fin"
                value={pickupTimeEnd}
                onChange={(e) => handleTimeChange('pickupTimeEnd', e?.target?.value)}
                required
              />
            </div>
          </div>

          {/* Return Days */}
          <div className="space-y-3">
            <label className="text-sm font-medium text-foreground">Jours de restitution disponibles</label>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
              {fullWeekDays?.map((day) => (
                <div key={`return-${day}`} className="flex items-center">
                  <Checkbox
                    label={day}
                    checked={returnDays?.includes(day)}
                    onChange={() => handleDayToggle(day, 'return')}
                  />
                </div>
              ))}
            </div>
          </div>

          {/* Return Time Range */}
          <div className="space-y-3">
            <label className="text-sm font-medium text-foreground">Horaires de restitution</label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <Input
                type="time"
                label="Heure de début"
                value={returnTimeStart}
                onChange={(e) => handleTimeChange('returnTimeStart', e?.target?.value)}
                required
              />
              <Input
                type="time"
                label="Heure de fin"
                value={returnTimeEnd}
                onChange={(e) => handleTimeChange('returnTimeEnd', e?.target?.value)}
                max="19:30"
                required
              />
            </div>
          </div>
        </div>
      </div>
      {/* Temporary Disable Option */}
      <div className="bg-surface rounded-lg border border-border p-4">
        <Checkbox
          label="Désactiver temporairement l'annonce"
          description="Votre annonce ne sera pas visible tant que cette option est activée"
          checked={formData?.temporarilyDisabled}
          onChange={(e) => updateFormData('temporarilyDisabled', e?.target?.checked)}
        />
      </div>
      {/* Info */}
      <div className="bg-[#17a2b8]/10 border border-[#17a2b8]/20 rounded-lg p-4">
        <div className="flex gap-2">
          <Icon name="Info" size={18} className="text-[#17a2b8] flex-shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-medium text-foreground mb-2">Gestion des disponibilités</p>
            <ul className="text-sm text-muted-foreground space-y-1">
              <li>• Cliquez sur une date pour la marquer comme indisponible</li>
              <li>• Vous pouvez modifier les disponibilités à tout moment</li>
              <li>• Les réservations confirmées bloquent automatiquement les dates</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DisponibilitesStep;

