import React, { useState } from 'react';
import { format, addMonths, subMonths, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay, isAfter, isBefore, startOfDay } from 'date-fns';
import { fr } from 'date-fns/locale';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const DateRangePicker = ({ startDate, endDate, onChange, unavailableDates = [], minDate = new Date() }) => {
  const [currentMonth, setCurrentMonth] = useState(startOfMonth(new Date()));
  const [selectingStart, setSelectingStart] = useState(true);

  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(currentMonth);
  const daysInMonth = eachDayOfInterval({ start: monthStart, end: monthEnd });

  const handlePreviousMonth = () => {
    setCurrentMonth(subMonths(currentMonth, 1));
  };

  const handleNextMonth = () => {
    setCurrentMonth(addMonths(currentMonth, 1));
  };

  const isDateUnavailable = (date) => {
    return unavailableDates?.some(unavailableDate => 
      isSameDay(startOfDay(date), startOfDay(unavailableDate))
    );
  };

  const isDateDisabled = (date) => {
    const dayStart = startOfDay(date);
    const minDateStart = startOfDay(minDate);
    return isBefore(dayStart, minDateStart) || isDateUnavailable(date);
  };

  const isDateInRange = (date) => {
    if (!startDate || !endDate) return false;
    const dayStart = startOfDay(date);
    return isAfter(dayStart, startOfDay(startDate)) && isBefore(dayStart, startOfDay(endDate));
  };

  const handleDateClick = (date) => {
    if (isDateDisabled(date)) return;

    if (selectingStart || !startDate) {
      onChange?.(date, null);
      setSelectingStart(false);
    } else {
      if (isBefore(date, startDate)) {
        // If clicked date is before start, set it as new start
        onChange?.(date, null);
      } else {
        // Check if there are unavailable dates in the range
        const hasUnavailableInRange = unavailableDates?.some(unavailableDate => {
          const unavailableDay = startOfDay(unavailableDate);
          return isAfter(unavailableDay, startOfDay(startDate)) && isBefore(unavailableDay, startOfDay(date));
        });

        if (hasUnavailableInRange) {
          // Reset selection if range contains unavailable dates
          onChange?.(date, null);
          setSelectingStart(false);
        } else {
          onChange?.(startDate, date);
          setSelectingStart(true);
        }
      }
    }
  };

  const weekDays = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];

  // Adjust days to start from Monday
  const getWeekDay = (date) => {
    const day = date?.getDay();
    return day === 0 ? 6 : day - 1; // Convert Sunday (0) to 6, and shift others
  };

  // Calculate offset for first day of month
  const firstDayOffset = getWeekDay(monthStart);

  return (
    <div className="space-y-4">
      {/* Calendar En-tête */}
      <div className="flex items-center justify-between">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handlePreviousMonth}
          iconName="ChevronLeft"
        />
        <h3 className="text-lg font-semibold capitalize">
          {format(currentMonth, 'MMMM yyyy', { locale: fr })}
        </h3>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleNextMonth}
          iconName="ChevronRight"
        />
      </div>

      {/* Week Days En-tête */}
      <div className="grid grid-cols-7 gap-1">
        {weekDays?.map(day => (
          <div key={day} className="text-center text-sm font-medium text-muted-foreground py-2">
            {day}
          </div>
        ))}
      </div>

      {/* Calendar Grid */}
      <div className="grid grid-cols-7 gap-1">
        {/* Empty cells for offset */}
        {Array.from({ length: firstDayOffset })?.map((_, index) => (
          <div key={`empty-${index}`} className="aspect-square" />
        ))}

        {/* Date cells */}
        {daysInMonth?.map(date => {
          const isDisabled = isDateDisabled(date);
          const isSelected = (startDate && isSameDay(date, startDate)) || (endDate && isSameDay(date, endDate));
          const isInRange = isDateInRange(date);
          const isToday = isSameDay(date, new Date());

          return (
            <button
              key={date?.toISOString()}
              type="button"
              onClick={() => handleDateClick(date)}
              disabled={isDisabled}
              className={cn(
                'aspect-square rounded-md text-sm font-medium transition-colors',
                'hover:bg-accent/20 focus:outline-none focus:ring-2 focus:ring-primary',
                isDisabled && 'opacity-30 cursor-not-allowed hover:bg-transparent line-through',
                isSelected && 'bg-primary text-primary-foreground hover:bg-primary/90',
                isInRange && !isSelected && 'bg-primary/20',
                isToday && !isSelected && 'border-2 border-primary',
                !isDisabled && !isSelected && !isInRange && 'hover:bg-accent/10'
              )}
            >
              {format(date, 'd')}
            </button>
          );
        })}
      </div>

      {/* Selected Dates Display */}
      {(startDate || endDate) && (
        <div className="flex items-center gap-2 p-3 bg-primary/5 rounded-md">
          <Icon name="Calendar" size={16} className="text-primary" />
          <div className="text-sm">
            {startDate && (
              <span className="font-medium">
                {format(startDate, 'dd MMM yyyy', { locale: fr })}
              </span>
            )}
            {startDate && endDate && <span className="mx-2">?</span>}
            {endDate && (
              <span className="font-medium">
                {format(endDate, 'dd MMM yyyy', { locale: fr })}
              </span>
            )}
          </div>
        </div>
      )}

      {/* Legend */}
      <div className="flex flex-wrap gap-4 text-xs text-muted-foreground">
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded border-2 border-primary" />
          <span>Aujourd'hui</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded bg-primary" />
          <span>Sélectionné</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded bg-muted line-through" />
          <span>Indisponible</span>
        </div>
      </div>
    </div>
  );
};

export default DateRangePicker;
