import React, { useState } from 'react';
import Header from '../../components/navigation/Header';
import Footer from '../../components/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';

const StripeConnectOnboarding = () => {
  const [stripeStatus, setStripeStatus] = useState('not_connected'); // not_connected, in_progress, connected
  const [loading, setLoading] = useState(false);

  // Mock user data
  const userData = {
    pseudonym: 'MarieDu',
    email: 'marie.dubois@example.com',
    stripeAccountId: stripeStatus === 'connected' ? 'acct_1234567890' : null,
    onboardingCompletedAt: stripeStatus === 'connected' ? '2026-02-10T14:30:00' : null
  };

  const getStatusConfig = () => {
    const configs = {
      not_connected: {
        label: 'Non connecté',
        icon: 'AlertCircle',
        color: 'text-muted-foreground bg-muted',
        description: 'Vous devez activer vos paiements pour recevoir des virements'
      },
      in_progress: {
        label: 'En cours',
        icon: 'Clock',
        color: 'text-warning bg-warning/10',
        description: 'Votre compte de paiement est en cours de vérification'
      },
      connected: {
        label: 'Connecté',
        icon: 'CheckCircle',
        color: 'text-success bg-success/10',
        description: 'Votre compte de paiement est actif et prêt à recevoir des virements'
      }
    };
    return configs?.[stripeStatus] || configs?.not_connected;
  };

  const handleCreateStripeAccount = async () => {
    setLoading(true);
    // Simulate API call to create Stripe Connect account
    setTimeout(() => {
      // In production, this would redirect to Stripe Connect onboarding
      window.open('https://connect.stripe.com/express/oauth/authorize', '_blank');
      setStripeStatus('in_progress');
      setLoading(false);
    }, 1000);
  };

  const handleAccessDashboard = () => {
    // En production, ceci redirige vers le tableau de bord Stripe Express
    window.open('https://dashboard.stripe.com', '_blank');
  };

  const statusConfig = getStatusConfig();

  const onboardingSteps = [
    {
      number: 1,
      title: 'Vérifier votre identité',
      description: 'Fournissez vos informations personnelles et une pièce d\'identité valide',
      icon: 'User',
      completed: stripeStatus === 'connected'
    },
    {
      number: 2,
      title: 'Ajouter vos coordonnées bancaires',
      description: 'Renseignez votre IBAN pour recevoir les paiements',
      icon: 'CreditCard',
      completed: stripeStatus === 'connected'
    },
    {
      number: 3,
      title: 'Commencer à recevoir des paiements',
      description: 'Une fois validé, vous pourrez publier vos annonces et recevoir des réservations',
      icon: 'DollarSign',
      completed: stripeStatus === 'connected'
    }
  ];

  const benefits = [
    {
      icon: 'Shield',
      title: 'Paiements sécurisés',
      description: 'Service de paiement Le Matos du Voisin garantit la sécurité de toutes vos transactions'
    },
    {
      icon: 'Zap',
      title: 'Virements rapides',
      description: 'Recevez vos paiements sous 2 à 7 jours ouvrables'
    },
    {
      icon: 'BarChart',
      title: 'Suivi en temps réel',
      description: 'Accédez à votre tableau de bord pour suivre vos revenus'
    },
    {
      icon: 'Lock',
      title: 'Protection des données',
      description: 'Vos informations bancaires sont cryptées et protégées'
    }
  ];

  return (
    <div className="min-h-screen flex flex-col bg-surface">
      <Header />
      
      <main className="flex-1 container mx-auto px-4 py-6 md:py-8">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-muted-foreground mb-6">
          <a href="/tableau-bord-utilisateur" className="hover:text-[#17a2b8] transition-colors">Tableau de bord</a>
          <Icon name="ChevronRight" size={14} />
          <span className="text-foreground">Activation des paiements</span>
        </div>

        {/* En-tête de page */}
        <div className="mb-8">
          <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-2">Activation des paiements</h1>
          <p className="text-muted-foreground">Configurez votre compte de paiement pour recevoir des virements</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Status Card */}
            <div className="bg-white rounded-lg shadow-elevation-1 p-6">
              <div className="flex items-start justify-between mb-4">
                <div className="flex-1">
                  <h2 className="text-xl font-semibold text-foreground mb-2">Statut de votre compte</h2>
                  <span className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium ${statusConfig?.color}`}>
                    <Icon name={statusConfig?.icon} size={16} />
                    {statusConfig?.label}
                  </span>
                  <p className="text-sm text-muted-foreground mt-3">{statusConfig?.description}</p>
                </div>
              </div>

              {stripeStatus === 'not_connected' && (
                <div className="mt-6">
                  <Button
                    size="lg"
                    iconName="ExternalLink"
                    onClick={handleCreateStripeAccount}
                    loading={loading}
                    className="bg-[#635bff] hover:bg-[#0a2540]"
                  >
                    Activer mes paiements
                  </Button>
                </div>
              )}

              {stripeStatus === 'in_progress' && (
                <div className="mt-6 bg-warning/10 border border-warning/20 rounded-lg p-4">
                  <div className="flex gap-3">
                    <Icon name="Clock" size={20} className="text-warning flex-shrink-0 mt-0.5" />
                    <div>
                      <p className="font-medium text-foreground mb-1">Vérification en cours</p>
                      <p className="text-sm text-muted-foreground">
                        Nous vérifions actuellement vos informations. Ce processus peut prendre quelques heures à quelques jours.
                        Vous recevrez un e-mail dès que votre compte sera activé.
                      </p>
                    </div>
                  </div>
                </div>
              )}

              {stripeStatus === 'connected' && (
                <div className="mt-6 space-y-4">
                  <div className="bg-success/10 border border-success/20 rounded-lg p-4">
                    <div className="flex gap-3">
                      <Icon name="CheckCircle" size={20} className="text-success flex-shrink-0 mt-0.5" />
                      <div>
                        <p className="font-medium text-foreground mb-1">Compte activé avec succès</p>
                        <p className="text-sm text-muted-foreground">
                          Votre compte de paiement est maintenant actif. Vous pouvez publier vos annonces et commencer à recevoir des réservations.
                        </p>
                      </div>
                    </div>
                  </div>

                  <div className="flex flex-col sm:flex-row gap-3">
                    <Button
                      variant="outline"
                      iconName="ExternalLink"
                      onClick={handleAccessDashboard}
                    >
                      Gérer mes paiements
                    </Button>
                    <Button
                      variant="default"
                      iconName="Plus"
                      onClick={() => window.location.href = '/creer-annonce'}
                    >
                      Créer une annonce
                    </Button>
                  </div>

                  {userData?.onboardingCompletedAt && (
                    <p className="text-xs text-muted-foreground">
                      Connecté le {new Date(userData?.onboardingCompletedAt)?.toLocaleDateString('fr-FR', {
                        day: '2-digit',
                        month: 'long',
                        year: 'numeric'
                      })}
                    </p>
                  )}
                </div>
              )}
            </div>

            {/* Onboarding Steps */}
            {stripeStatus !== 'connected' && (
              <div className="bg-white rounded-lg shadow-elevation-1 p-6">
                <h2 className="text-xl font-semibold text-foreground mb-6">Les étapes de l'inscription</h2>
                <div className="space-y-6">
                  {onboardingSteps?.map((step) => (
                    <div key={step?.number} className="flex gap-4">
                      <div className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 ${
                        step?.completed ? 'bg-success text-white' : 'bg-surface text-muted-foreground'
                      }`}>
                        {step?.completed ? (
                          <Icon name="Check" size={20} />
                        ) : (
                          <Icon name={step?.icon} size={20} />
                        )}
                      </div>
                      <div className="flex-1">
                        <h3 className="font-semibold text-foreground mb-1">
                          {step?.number}. {step?.title}
                        </h3>
                        <p className="text-sm text-muted-foreground">{step?.description}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Important Notice */}
            <div className="bg-[#17a2b8]/10 border border-[#17a2b8]/20 rounded-lg p-4">
              <div className="flex gap-3">
                <Icon name="Info" size={20} className="text-[#17a2b8] flex-shrink-0 mt-0.5" />
                <div>
                  <p className="font-medium text-foreground mb-1">Information importante</p>
                  <p className="text-sm text-muted-foreground">
                    L'activation de votre compte de paiement est <strong>obligatoire</strong> pour publier des annonces et recevoir des paiements.
                    Sans compte de paiement activé, vous ne pourrez pas louer vos équipements sur la plateforme.
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Benefits */}
            <div className="bg-white rounded-lg shadow-elevation-1 p-6">
              <h3 className="font-semibold text-foreground mb-4 flex items-center gap-2">
                <Icon name="Star" size={18} />
                Pourquoi notre service de paiement ?
              </h3>
              <div className="space-y-4">
                {benefits?.map((benefit, index) => (
                  <div key={index} className="flex gap-3">
                    <div className="w-10 h-10 bg-[#17a2b8]/10 rounded-lg flex items-center justify-center flex-shrink-0">
                      <Icon name={benefit?.icon} size={18} className="text-[#17a2b8]" />
                    </div>
                    <div>
                      <p className="font-medium text-foreground text-sm mb-1">{benefit?.title}</p>
                      <p className="text-xs text-muted-foreground">{benefit?.description}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Help Section */}
            <div className="bg-white rounded-lg shadow-elevation-1 p-6">
              <h3 className="font-semibold text-foreground mb-4 flex items-center gap-2">
                <Icon name="HelpCircle" size={18} />
                Besoin d'aide ?
              </h3>
              <p className="text-sm text-muted-foreground mb-4">
                Si vous rencontrez des difficultés lors de l'activation de votre compte de paiement, consultez notre FAQ ou contactez notre support.
              </p>
              <div className="flex flex-col gap-2">
                <Button variant="outline" size="sm" iconName="Book">
                  Consulter la FAQ
                </Button>
                <Button variant="outline" size="sm" iconName="MessageSquare">
                  Contacter le support
                </Button>
              </div>
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default StripeConnectOnboarding;

