import { supabase } from '../lib/supabase';

/**
 * Envoyer un courriel via Resend et la fonction Edge Supabase
 * @param {Object} params - Parametres du courriel
 * @param {string|string[]} params.to - Destinataire(s) du courriel
 * @param {string} params.templateKey - Cle du modele de courriel en base
 * @param {Object} params.variables - Variables a substituer dans le modele
 * @param {string} params.subject - Sujet de remplacement (optionnel)
 * @param {string} params.htmlBody - Corps HTML de remplacement (optionnel)
 * @param {string} params.textBody - Corps texte (optionnel)
 * @returns {Promise<{success: boolean, messageId?: string, error?: string}>}
 */
export async function sendEmail({ to, templateKey, variables = {}, subject, htmlBody, textBody }) {
  try {
    let finalSubject = subject;
    let finalHtmlBody = htmlBody;
    let finalTextBody = textBody;

    if (templateKey) {
      const { data: template, error: templateError } = await supabase
        ?.from('email_templates')
        ?.select('subject, body_html, body_text, enabled')
        ?.eq('key', templateKey)
        ?.single();

      if (templateError) {
        console.error(`Modele de courriel '${templateKey}' introuvable :`, templateError);
        await logFailedEmail(to, templateKey, variables, `Modele introuvable : ${templateError?.message}`);
        return { success: false, error: `Modele '${templateKey}' introuvable` };
      }

      if (!template?.enabled) {
        console.warn(`Modele de courriel '${templateKey}' desactive`);
        return { success: false, error: `Modele '${templateKey}' desactive` };
      }

      finalSubject = finalSubject || template?.subject;
      finalHtmlBody = finalHtmlBody || template?.body_html;
      finalTextBody = finalTextBody || template?.body_text;
    }

    if (!to || !finalSubject || !finalHtmlBody) {
      const error = 'Champs requis manquants : destinataire, sujet et corps HTML';
      console.error(error);
      await logFailedEmail(to, templateKey, variables, error);
      return { success: false, error };
    }

    const { data, error } = await supabase?.functions?.invoke('send-email', {
      body: {
        to,
        subject: finalSubject,
        htmlBody: finalHtmlBody,
        textBody: finalTextBody,
        templateKey,
        variables
      }
    });

    if (error) {
      console.error('Erreur d\'envoi de courriel :', error);
      await logFailedEmail(to, templateKey, variables, error?.message);
      return { success: false, error: error?.message };
    }

    await logSuccessfulEmail(to, templateKey, variables);

    return { success: true, messageId: data?.messageId };
  } catch (error) {
    console.error('Erreur inattendue de courriel :', error);
    await logFailedEmail(to, templateKey, variables, error?.message);
    return { success: false, error: error?.message };
  }
}

async function logFailedEmail(to, templateKey, variables, errorMessage) {
  try {
    await supabase?.from('email_queue')?.insert({
      recipient_email: Array.isArray(to) ? to?.[0] : to,
      template_key: templateKey,
      variables: variables || {},
      status: 'failed',
      last_error: errorMessage,
      attempts: 1
    });
  } catch (err) {
    console.error('Echec de journalisation de l\'erreur de courriel :', err);
  }
}

async function logSuccessfulEmail(to, templateKey, variables) {
  try {
    await supabase?.from('email_queue')?.insert({
      recipient_email: Array.isArray(to) ? to?.[0] : to,
      template_key: templateKey,
      variables: variables || {},
      status: 'sent',
      sent_at: new Date()?.toISOString()
    });
  } catch (err) {
    console.error('Echec de journalisation du succes du courriel :', err);
  }
}

