import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import Icon from '../AppIcon';
import UserMenu from './UserMenu';
import { useAuth } from '../../contexts/AuthContext';

const Header = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const location = useLocation();
  const mobileMenuRef = useRef(null);
  const { user, loading } = useAuth();
  const isAuthenticated = !loading && !!user;

  const publicNavigationItems = [
    {
      label: 'Accueil',
      path: '/accueil-recherche',
      icon: 'Home'
    },
    {
      label: 'Demandes',
      path: '/demandes-publiques',
      icon: 'Search'
    },
    {
      label: 'Créer une annonce',
      path: '/creer-annonce',
      icon: 'Plus'
    },
    {
      label: 'Créer une demande',
      path: '/creer-demande',
      icon: 'FileSearch'
    }
  ];

  const privateNavigationItems = [
    {
      label: 'Mes Annonces',
      path: '/mes-annonces',
      icon: 'Package'
    },
    {
      label: 'Mes Réservations',
      path: '/mes-reservations',
      icon: 'Calendar'
    },
    {
      label: 'Messages',
      path: '/messages',
      icon: 'MessageSquare',
      badge: 3
    }
  ];

  const navigationItems = isAuthenticated
    ? [...publicNavigationItems, ...privateNavigationItems]
    : publicNavigationItems;

  if (isAuthenticated && user?.is_admin) {
    navigationItems?.push({
      label: 'Administration',
      path: '/administration-tableau-bord',
      icon: 'Shield'
    });
  }

  const unreadCount = 0; // Will be replaced with real notification count from Supabase

  const formatTimestamp = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);

    if (diffMins < 60) {
      return `Il y a ${diffMins} min`;
    }

    if (diffHours < 24) {
      return `Il y a ${diffHours}h`;
    }

    return date?.toLocaleDateString('fr-FR', {
      day: '2-digit',
      month: 'short'
    });
  };

  const isActivePath = (path) => {
    return location?.pathname === path;
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (mobileMenuRef?.current && !mobileMenuRef?.current?.contains(event?.target)) {
        closeMobileMenu();
      }
    };

    if (isMobileMenuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.body.style.overflow = 'unset';
    };
  }, [isMobileMenuOpen]);

  useEffect(() => {
    closeMobileMenu();
  }, [location?.pathname]);

  useEffect(() => {
    if (!isAuthenticated && showNotifications) {
      setShowNotifications(false);
    }
  }, [isAuthenticated, showNotifications]);

  return (
    <>
      <header className="header-container">
        <div className="header-content">
          <Link to="/accueil-recherche" className="header-logo">
            <img
              src="/assets/images/android-chrome-192x192-1771179342850.png"
              alt="Logo Le Matos Du Voisin - poignée de main formant un cœur"
              className="header-logo-image"
            />
          </Link>

          <nav className="header-nav">
            {navigationItems?.map((item) => (
              <Link
                key={item?.path}
                to={item?.path}
                className={`header-nav-item ${isActivePath(item?.path) ? 'active' : ''}`}
              >
                <Icon name={item?.icon} size={20} />
                <span>{item?.label}</span>
                {item?.badge && (
                  <span className="notification-badge">{item?.badge}</span>
                )}
              </Link>
            ))}
          </nav>

          <div className="header-actions">
            {isAuthenticated ? (
              <>
                <div className="relative">
                  <button
                    onClick={() => setShowNotifications(!showNotifications)}
                    className="relative flex items-center justify-center w-10 h-10 rounded-lg transition-colors hover:bg-surface"
                  >
                    <Icon name="Bell" size={24} />
                    {unreadCount > 0 && (
                      <span className="notification-badge">
                        {unreadCount > 99 ? '99+' : unreadCount}
                      </span>
                    )}
                  </button>

                  {showNotifications && (
                    <div className="absolute right-0 mt-2 w-80 bg-white rounded-lg shadow-elevation-4 border border-border z-50">
                      <div className="p-4 border-b border-border flex items-center justify-between">
                        <h3 className="font-semibold text-foreground">Notifications</h3>
                        <Link
                          to="/centre-notifications"
                          className="text-sm text-[#17a2b8] hover:text-[#138496]"
                          onClick={() => setShowNotifications(false)}
                        >
                          Voir tout
                        </Link>
                      </div>
                      <div className="max-h-96 overflow-y-auto">
                        {[
                          {
                            id: 1,
                            title: 'Nouvelle demande',
                            message: 'Pierre_M souhaite louer votre perceuse',
                            timestamp: '2026-02-14T10:30:00',
                            read: false,
                            icon: 'Calendar'
                          },
                          {
                            id: 2,
                            title: 'Nouveau message',
                            message: 'Marie_L vous a envoyé un message',
                            timestamp: '2026-02-14T09:15:00',
                            read: false,
                            icon: 'MessageSquare'
                          },
                          {
                            id: 3,
                            title: 'Paiement validé',
                            message: 'Le paiement de 45,00 € a été validé',
                            timestamp: '2026-02-13T16:45:00',
                            read: true,
                            icon: 'CheckCircle'
                          }
                        ]?.slice(0, 5)?.map((notification) => (
                          <div
                            key={notification?.id}
                            className={`p-4 border-b border-border hover:bg-surface transition-colors cursor-pointer ${
                              !notification?.read ? 'bg-[#17a2b8]/5' : ''
                            }`}
                          >
                            <div className="flex gap-3">
                              <Icon name={notification?.icon} size={20} className="text-[#17a2b8] flex-shrink-0" />
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-foreground">{notification?.title}</p>
                                <p className="text-xs text-muted-foreground mt-1">{notification?.message}</p>
                                <p className="text-xs text-muted-foreground mt-1">{formatTimestamp(notification?.timestamp)}</p>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <UserMenu />
              </>
            ) : (
              <Link
                to="/authentification"
                className="inline-flex items-center justify-center h-10 px-4 rounded-lg bg-[#2647c8] text-white font-medium transition-colors hover:bg-[#1f3ba8]"
              >
                Se connecter
              </Link>
            )}
          </div>
        </div>
      </header>
      <button
        className="mobile-menu-button"
        onClick={toggleMobileMenu}
        aria-label="Toggle mobile menu"
      >
        <Icon name={isMobileMenuOpen ? 'X' : 'Menu'} size={24} />
      </button>
      <div
        ref={mobileMenuRef}
        className={`mobile-menu-overlay ${isMobileMenuOpen ? 'open' : 'closed'}`}
      >
        <div className="mobile-menu-content">
          <nav className="mobile-menu-nav">
            {navigationItems?.map((item) => (
              <Link
                key={item?.path}
                to={item?.path}
                className={`mobile-menu-nav-item ${isActivePath(item?.path) ? 'active' : ''}`}
              >
                <Icon name={item?.icon} size={24} />
                <span>{item?.label}</span>
                {item?.badge && (
                  <span className="notification-badge">{item?.badge}</span>
                )}
              </Link>
            ))}
          </nav>

          <div className="mt-auto pt-4 border-t border-border">
            {isAuthenticated ? (
              <UserMenu isMobile={true} />
            ) : (
              <Link
                to="/authentification"
                className="block text-center w-full px-4 py-3 rounded-lg bg-[#2647c8] text-white font-medium transition-colors hover:bg-[#1f3ba8]"
              >
                Se connecter
              </Link>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

export default Header;
