import { supabase } from '../lib/supabase';
import { sendEmail } from './emailService';

/**
 * Check for owners who haven't responded to reservation requests
 * Send reminders, create strikes, auto-cancel after deadlines
 */
export const checkOwnerNoResponse = async () => {
  try {
    const now = new Date();
    const results = { reminders: 0, strikes: 0, cancelled: 0, errors: [] };

    // Get pending reservations with expired deadlines
    const { data: reservations, error } = await supabase?.from('reservations')?.select('*, owner:owner_id(id, email, pseudo)')?.eq('status', 'pending')?.is('owner_confirmed_at', null)?.lt('owner_reply_deadline_at', now?.toISOString());

    if (error) throw error;

    for (const reservation of reservations || []) {
      const hoursOverdue = Math.floor(
        (now - new Date(reservation.owner_reply_deadline_at)) / (1000 * 60 * 60)
      );

      try {
        if (hoursOverdue >= 72) {
          // Auto-cancel after 72h
          await supabase?.from('reservations')?.update({ 
              status: 'cancelled_owner_no_reply',
              cancelled_at: now?.toISOString(),
              cancellation_reason: 'Propriétaire n\'a pas répondu dans les délais'
            })?.eq('id', reservation?.id);

          // Create strike
          await supabase?.from('user_sanctions')?.insert({
            user_id: reservation?.owner_id,
            type: 'strike',
            reason: 'Non-réponse à une demande de réservation (72h)',
            reservation_id: reservation?.id,
            created_by: null // System
          });

          results.cancelled++;
          results.strikes++;
        } else if (hoursOverdue >= 48) {
          // Send reminder and create strike at 48h
          await sendEmail({
            to: reservation?.owner?.email,
            template: 'owner_no_response_strike',
            data: {
              ownerName: reservation?.owner?.pseudo,
              reservationId: reservation?.id,
              hoursOverdue
            }
          });

          await supabase?.from('user_sanctions')?.insert({
            user_id: reservation?.owner_id,
            type: 'strike',
            reason: 'Non-réponse à une demande de réservation (48h)',
            reservation_id: reservation?.id,
            created_by: null
          });

          results.strikes++;
        } else if (hoursOverdue >= 24) {
          // Send reminder at 24h
          await sendEmail({
            to: reservation?.owner?.email,
            template: 'owner_no_response_reminder',
            data: {
              ownerName: reservation?.owner?.pseudo,
              reservationId: reservation?.id,
              hoursRemaining: 72 - hoursOverdue
            }
          });

          results.reminders++;
        }
      } catch (err) {
        results?.errors?.push({ reservationId: reservation?.id, error: err?.message });
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans checkOwnerNoResponse:', error);
    throw error;
  }
};

/**
 * Check for missing documents and send reminders
 */
export const checkMissingDocuments = async () => {
  try {
    const results = { reminders: 0, errors: [] };
    const threeDaysFromNow = new Date();
    threeDaysFromNow?.setDate(threeDaysFromNow?.getDate() + 3);

    // Get reservations with incomplete docs approaching deadline
    const { data: reservations, error } = await supabase?.from('reservations')?.select(`
        *,
        renter:renter_id(id, email, pseudo),
        reservation_docs(*)
      `)?.in('status', ['accepted', 'paid'])?.lt('tenant_docs_due_at', threeDaysFromNow?.toISOString());

    if (error) throw error;

    for (const reservation of reservations || []) {
      const docs = reservation?.reservation_docs?.[0];
      const missingDocs = [];

      if (!docs?.id_ok) missingDocs?.push('Pièce d\'identité');
      if (!docs?.rc_ok) missingDocs?.push('Attestation RC');
      if (!docs?.address_ok) missingDocs?.push('Justificatif de domicile');

      if (missingDocs?.length > 0) {
        try {
          await sendEmail({
            to: reservation?.renter?.email,
            template: 'missing_documents_reminder',
            data: {
              renterName: reservation?.renter?.pseudo,
              reservationId: reservation?.id,
              missingDocs: missingDocs?.join(', '),
              dueDate: new Date(reservation.tenant_docs_due_at)?.toLocaleDateString('fr-FR')
            }
          });

          results.reminders++;
        } catch (err) {
          results?.errors?.push({ reservationId: reservation?.id, error: err?.message });
        }
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans checkMissingDocuments:', error);
    throw error;
  }
};

/**
 * Cancel unpaid reservations after payment deadline
 */
export const cancelUnpaidReservations = async () => {
  try {
    const now = new Date();
    const results = { cancelled: 0, errors: [] };

    const { data: reservations, error } = await supabase?.from('reservations')?.select('*')?.eq('status', 'accepted')?.is('paid_at', null)?.lt('payment_deadline', now?.toISOString());

    if (error) throw error;

    for (const reservation of reservations || []) {
      try {
        await supabase?.from('reservations')?.update({
            status: 'cancelled_tenant_no_payment',
            cancelled_at: now?.toISOString(),
            cancellation_reason: 'Paiement non effectué dans les délais'
          })?.eq('id', reservation?.id);

        results.cancelled++;
      } catch (err) {
        results?.errors?.push({ reservationId: reservation?.id, error: err?.message });
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans cancelUnpaidReservations:', error);
    throw error;
  }
};

/**
 * Release deposit authorizations after rental completion + 7 days
 */
export const releaseDeposits = async () => {
  try {
    const sevenDaysAgo = new Date();
    sevenDaysAgo?.setDate(sevenDaysAgo?.getDate() - 7);
    const results = { released: 0, errors: [] };

    const { data: reservations, error } = await supabase?.from('reservations')?.select('*')?.eq('status', 'completed')?.eq('deposit_status', 'authorized')?.lt('end_date', sevenDaysAgo?.toISOString());

    if (error) throw error;

    for (const reservation of reservations || []) {
      try {
        // In production, call Stripe API to release authorization
        // For now, just update status
        await supabase?.from('reservations')?.update({
            deposit_status: 'released',
            deposit_released_at: new Date()?.toISOString()
          })?.eq('id', reservation?.id);

        results.released++;
      } catch (err) {
        results?.errors?.push({ reservationId: reservation?.id, error: err?.message });
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans releaseDeposits:', error);
    throw error;
  }
};

/**
 * Send return reminders 2 days before end date
 */
export const sendReturnReminders = async () => {
  try {
    const twoDaysFromNow = new Date();
    twoDaysFromNow?.setDate(twoDaysFromNow?.getDate() + 2);
    const results = { sent: 0, errors: [] };

    const { data: reservations, error } = await supabase?.from('reservations')?.select('*, renter:renter_id(email, pseudo), annonce:annonce_id(titre)')?.eq('status', 'active')?.gte('end_date', twoDaysFromNow?.toISOString())?.lt('end_date', new Date(twoDaysFromNow.getTime() + 24 * 60 * 60 * 1000)?.toISOString());

    if (error) throw error;

    for (const reservation of reservations || []) {
      try {
        await sendEmail({
          to: reservation?.renter?.email,
          template: 'return_reminder',
          data: {
            renterName: reservation?.renter?.pseudo,
            equipmentTitle: reservation?.annonce?.titre,
            returnDate: new Date(reservation.end_date)?.toLocaleDateString('fr-FR')
          }
        });

        results.sent++;
      } catch (err) {
        results?.errors?.push({ reservationId: reservation?.id, error: err?.message });
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans sendReturnReminders:', error);
    throw error;
  }
};

/**
 * Process strikes and auto-ban users with 3+ strikes
 */
export const processStrikes = async () => {
  try {
    const results = { banned: 0, errors: [] };

    // Get users with 3+ strikes
    const { data: users, error } = await supabase?.from('user_profiles')?.select('id, email, pseudo, no_reply_strikes')?.gte('no_reply_strikes', 3)?.is('banned_at', null);

    if (error) throw error;

    for (const user of users || []) {
      try {
        await supabase?.from('user_profiles')?.update({
            banned_at: new Date()?.toISOString(),
            ban_reason: 'Récidive non-réponse (3 strikes ou plus)'
          })?.eq('id', user?.id);

        await sendEmail({
          to: user?.email,
          template: 'account_banned',
          data: {
            userName: user?.pseudo,
            reason: 'Récidive non-réponse',
            strikes: user?.no_reply_strikes
          }
        });

        results.banned++;
      } catch (err) {
        results?.errors?.push({ userId: user?.id, error: err?.message });
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans processStrikes:', error);
    throw error;
  }
};

/**
 * Clean expired deposit holds (7+ days old)
 */
export const cleanExpiredHolds = async () => {
  try {
    const sevenDaysAgo = new Date();
    sevenDaysAgo?.setDate(sevenDaysAgo?.getDate() - 7);
    const results = { cleaned: 0, errors: [] };

    const { data: payments, error } = await supabase?.from('payments')?.select('*')?.eq('type', 'deposit_hold')?.eq('status', 'requires_capture')?.lt('created_at', sevenDaysAgo?.toISOString());

    if (error) throw error;

    for (const payment of payments || []) {
      try {
        // In production, call Stripe API to cancel hold
        await supabase?.from('payments')?.update({ status: 'cancelled' })?.eq('id', payment?.id);

        results.cleaned++;
      } catch (err) {
        results?.errors?.push({ paymentId: payment?.id, error: err?.message });
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans cleanExpiredHolds:', error);
    throw error;
  }
};

/**
 * Send daily digest of unread notifications
 */
export const sendDailyDigest = async () => {
  try {
    const results = { sent: 0, errors: [] };

    // Get users with unread notifications
    const { data: notifications, error } = await supabase?.from('notifications')?.select('user_id, user:user_id(email, pseudo)')?.eq('read', false)?.gte('created_at', new Date(Date.now() - 24 * 60 * 60 * 1000)?.toISOString());

    if (error) throw error;

    // Group by user
    const userNotifications = {};
    notifications?.forEach(notif => {
      if (!userNotifications?.[notif?.user_id]) {
        userNotifications[notif.user_id] = {
          user: notif?.user,
          count: 0
        };
      }
      userNotifications[notif.user_id].count++;
    });

    for (const [userId, data] of Object.entries(userNotifications)) {
      try {
        await sendEmail({
          to: data?.user?.email,
          template: 'daily_digest',
          data: {
            userName: data?.user?.pseudo,
            notificationCount: data?.count
          }
        });

        results.sent++;
      } catch (err) {
        results?.errors?.push({ userId, error: err?.message });
      }
    }

    return results;
  } catch (error) {
    console.error('Erreur dans sendDailyDigest:', error);
    throw error;
  }
};

/**
 * Exécuter toutes les automatisations
 */
export const runAllAutomations = async () => {
  const results = {};

  try {
    results.ownerNoResponse = await checkOwnerNoResponse();
  } catch (error) {
    results.ownerNoResponse = { error: error?.message };
  }

  try {
    results.missingDocuments = await checkMissingDocuments();
  } catch (error) {
    results.missingDocuments = { error: error?.message };
  }

  try {
    results.unpaidReservations = await cancelUnpaidReservations();
  } catch (error) {
    results.unpaidReservations = { error: error?.message };
  }

  try {
    results.depositRelease = await releaseDeposits();
  } catch (error) {
    results.depositRelease = { error: error?.message };
  }

  try {
    results.returnReminders = await sendReturnReminders();
  } catch (error) {
    results.returnReminders = { error: error?.message };
  }

  try {
    results.strikes = await processStrikes();
  } catch (error) {
    results.strikes = { error: error?.message };
  }

  try {
    results.expiredHolds = await cleanExpiredHolds();
  } catch (error) {
    results.expiredHolds = { error: error?.message };
  }

  try {
    results.dailyDigest = await sendDailyDigest();
  } catch (error) {
    results.dailyDigest = { error: error?.message };
  }

  // Log to job_runs table
  try {
    await supabase?.from('job_runs')?.insert({
      action: 'run_all_automations',
      status: 'completed',
      result: results,
      executed_at: new Date()?.toISOString()
    });
  } catch (logError) {
    console.error("Échec de journalisation d'exécution d'automatisation :", logError);
  }

  return results;
};

