import React, { useState } from 'react';
import Header from '../../components/navigation/Header';
import Footer from '../../components/Footer';
import Icon from '../../components/AppIcon';

import Select from '../../components/ui/Select';
import ReservationCard from './components/ReservationCard';
import ReservationTimelineModal from './components/ReservationTimelineModal';
import AcceptRejectModal from './components/AcceptRejectModal';
import ContractPreviewModal from './components/ContractPreviewModal';

const ReservationManagementDashboard = () => {
  const [statusFilter, setStatusFilter] = useState('all');
  const [selectedReservation, setSelectedReservation] = useState(null);
  const [showTimelineModal, setShowTimelineModal] = useState(false);
  const [showAcceptRejectModal, setShowAcceptRejectModal] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [actionType, setActionType] = useState(null); // 'accept' or 'reject'

  const reservations = [
  {
    id: 'RES-2026-001',
    equipmentTitle: 'Perceuse sans fil Bosch Professional',
    equipmentImage: '/assets/images/no_image.png',
    equipmentImageAlt: 'Professional Bosch cordless drill with battery pack and carrying case on white background',
    renterPseudo: 'Marie_L',
    renterAvatar: "/assets/images/no_image.png",
    startDate: '2026-02-20',
    endDate: '2026-02-23',
    status: 'pending',
    totalAmount: 75.00,
    cautionAmount: 150.00,
    cautionStatus: 'pending',
    requestDate: '2026-02-14T10:30:00',
    timeline: [
    { date: '2026-02-14T10:30:00', event: 'Demande de réservation créée', type: 'info' },
    { date: '2026-02-14T11:00:00', event: 'En attente de validation propriétaire', type: 'pending' }]

  },
  {
    id: 'RES-2026-002',
    equipmentTitle: 'Tondeuse thermique Honda',
    equipmentImage: 'https://images.unsplash.com/photo-1693841956318-7afde7ab264e',
    equipmentImageAlt: 'Red Honda gasoline lawn mower with grass catcher on green lawn',
    renterPseudo: 'Pierre_M',
    renterAvatar: "https://images.unsplash.com/photo-1693841956318-7afde7ab264e",
    startDate: '2026-02-15',
    endDate: '2026-02-16',
    status: 'ongoing',
    totalAmount: 45.00,
    cautionAmount: 200.00,
    cautionStatus: 'authorized',
    requestDate: '2026-02-13T09:00:00',
    timeline: [
    { date: '2026-02-13T09:00:00', event: 'Demande créée', type: 'info' },
    { date: '2026-02-13T14:30:00', event: 'Acceptée par le propriétaire', type: 'success' },
    { date: '2026-02-14T16:00:00', event: 'Paiement effectué', type: 'success' },
    { date: '2026-02-15T09:30:00', event: 'Équipement récupéré', type: 'success' }]

  },
  {
    id: 'RES-2026-003',
    equipmentTitle: 'Échelle télescopique 5m',
    equipmentImage: '/assets/images/no_image.png',
    equipmentImageAlt: 'Telescopic aluminum ladder extended to full height against white background',
    renterPseudo: 'Sophie_D',
    renterAvatar: "/assets/images/no_image.png",
    startDate: '2026-02-10',
    endDate: '2026-02-12',
    status: 'completed',
    totalAmount: 36.00,
    cautionAmount: 100.00,
    cautionStatus: 'released',
    requestDate: '2026-02-08T10:00:00',
    timeline: [
    { date: '2026-02-08T10:00:00', event: 'Demande créée', type: 'info' },
    { date: '2026-02-08T15:20:00', event: 'Acceptée', type: 'success' },
    { date: '2026-02-09T11:00:00', event: 'Paiement effectué', type: 'success' },
    { date: '2026-02-10T08:45:00', event: 'Équipement récupéré', type: 'success' },
    { date: '2026-02-12T18:30:00', event: 'Équipement restitué', type: 'success' },
    { date: '2026-02-12T19:00:00', event: 'Caution libérée', type: 'success' }]

  }];


  const getStatusConfig = (status) => {
    const configs = {
      pending: {
        label: 'En attente',
        icon: 'Clock',
        color: 'text-warning bg-warning/10'
      },
      ongoing: {
        label: 'En cours',
        icon: 'PlayCircle',
        color: 'text-[#17a2b8] bg-[#17a2b8]/10'
      },
      completed: {
        label: 'Terminée',
        icon: 'CheckCircle',
        color: 'text-success bg-success/10'
      },
      cancelled: {
        label: 'Annulée',
        icon: 'XCircle',
        color: 'text-muted-foreground bg-muted'
      }
    };
    return configs?.[status] || configs?.pending;
  };

  const filteredReservations = statusFilter === 'all' ?
  reservations :
  reservations?.filter((r) => r?.status === statusFilter);

  const statusOptions = [
  { value: 'all', label: 'Toutes' },
  { value: 'pending', label: 'En attente' },
  { value: 'ongoing', label: 'En cours' },
  { value: 'completed', label: 'Terminées' },
  { value: 'cancelled', label: 'Annulées' }];


  const stats = [
  {
    label: 'En attente',
    value: reservations?.filter((r) => r?.status === 'pending')?.length,
    icon: 'Clock',
    color: 'text-warning bg-warning/10'
  },
  {
    label: 'En cours',
    value: reservations?.filter((r) => r?.status === 'ongoing')?.length,
    icon: 'PlayCircle',
    color: 'text-[#17a2b8] bg-[#17a2b8]/10'
  },
  {
    label: 'Terminées',
    value: reservations?.filter((r) => r?.status === 'completed')?.length,
    icon: 'CheckCircle',
    color: 'text-success bg-success/10'
  }];


  const handleViewTimeline = (reservation) => {
    setSelectedReservation(reservation);
    setShowTimelineModal(true);
  };

  const handleViewContract = (reservation) => {
    setSelectedReservation(reservation);
    setShowContractModal(true);
  };

  const handleAccept = (reservation) => {
    setSelectedReservation(reservation);
    setActionType('accept');
    setShowAcceptRejectModal(true);
  };

  const handleReject = (reservation) => {
    setSelectedReservation(reservation);
    setActionType('reject');
    setShowAcceptRejectModal(true);
  };

  const handleActionSubmit = (message) => {
    console.log(`${actionType} reservation:`, selectedReservation?.id, 'Message:', message);
    // API call to accept/reject reservation
    setShowAcceptRejectModal(false);
    setSelectedReservation(null);
    setActionType(null);
  };

  const handleCancel = (reservationId) => {
    console.log('Cancel reservation:', reservationId);
    // API call to cancel reservation
  };

  return (
    <div className="min-h-screen flex flex-col bg-background">
      <Header />
      <main className="flex-1 container mx-auto px-4 py-8">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-muted-foreground mb-6">
          <a href="/tableau-bord-utilisateur" className="hover:text-[#17a2b8] transition-colors">Tableau de bord</a>
          <Icon name="ChevronRight" size={14} />
          <span className="text-foreground">Mes réservations</span>
        </div>

        {/* En-tête de page */}
        <div className="mb-6">
          <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-2">Gestion des réservations</h1>
          <p className="text-muted-foreground">Gérez vos demandes de réservation et suivez leur statut</p>
        </div>

        {/* Cartes de statistiques */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          {stats?.map((stat, index) =>
          <div key={index} className="bg-white rounded-lg shadow-elevation-1 p-4 md:p-6">
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="text-sm text-muted-foreground mb-1">{stat?.label}</p>
                  <p className="text-3xl font-bold text-foreground">{stat?.value}</p>
                </div>
                <div className={`p-3 rounded-lg ${stat?.color}`}>
                  <Icon name={stat?.icon} size={24} />
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg shadow-elevation-1 p-4 mb-6">
          <Select
            options={statusOptions}
            value={statusFilter}
            onChange={setStatusFilter}
            placeholder="Filtrer par statut" />
          
        </div>

        {/* Reservations List */}
        <div className="space-y-4">
          {filteredReservations?.length === 0 ?
          <div className="bg-white rounded-lg shadow-elevation-1 p-12 text-center">
              <Icon name="Calendar" size={48} className="mx-auto text-muted-foreground mb-3" />
              <p className="text-muted-foreground">Aucune réservation trouvée</p>
            </div> :

          filteredReservations?.map((reservation) =>
          <ReservationCard
            key={reservation?.id}
            reservation={reservation}
            statusConfig={getStatusConfig(reservation?.status)}
            onViewTimeline={handleViewTimeline}
            onAccept={handleAccept}
            onReject={handleReject}
            onCancel={handleCancel}
            onViewContract={handleViewContract} />

          )
          }
        </div>

        {/* Contract Preview Modal */}
        {showContractModal && selectedReservation?.contractUrl &&
        <ContractPreviewModal
          reservation={selectedReservation}
          contractUrl={selectedReservation?.contractUrl}
          onClose={() => {
            setShowContractModal(false);
            setSelectedReservation(null);
          }} />

        }
      </main>
      <Footer />
      {/* Modals */}
      {showTimelineModal && selectedReservation &&
      <ReservationTimelineModal
        reservation={selectedReservation}
        onClose={() => setShowTimelineModal(false)} />

      }
      {showAcceptRejectModal && selectedReservation &&
      <AcceptRejectModal
        reservation={selectedReservation}
        actionType={actionType}
        onClose={() => setShowAcceptRejectModal(false)}
        onSubmit={handleActionSubmit} />

      }
    </div>);


};

export default ReservationManagementDashboard;

